'use strict';
const {money,uid,dayShift,stages,scoreKeys,alertFor}=TH;
const KEY='top-hills-journal-v1';
const basketSrc=window.TH_ASSET_BASKET||'assets/laundry-basket.png';
let storageOK=true,loadWarning='';
let db=(()=>{try{const raw=localStorage.getItem(KEY);if(!raw)return TH.seed();const v=JSON.parse(raw);if(!TH.validateBackup(v))throw Error('invalid');return v;}catch(e){storageOK=false;loadWarning='Data lokal belum bisa dibaca. Sesi demo dibuka; cadangkan perubahan sebelum menutup.';return TH.seed();}})();
let ui={role:'Owner',employee:db.employees.find(e=>e.active)?.id||'',consumer:'t1',page:'home',tab:'laundry',date:db.settings.date,search:'',filter:'Semua',view:'list',selected:null};
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',laundry:'<rect x="4" y="2" width="16" height="20" rx="3"/><circle cx="12" cy="14" r="5"/><path d="M7 6h.01M10 6h.01M15 6h2M8 14q4-4 8 0"/>',book:'<path d="M12 5v16M3 3q6-1 9 2 3-3 9-2v16q-6-1-9 2-3-3-9-2z"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8V5l14-3v3M16 12h5v5h-5z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM13 6l5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1"/>',shield:'<path d="m12 2 9 4v7q-1 6-9 9-8-3-9-9V6z"/><path d="m8 12 3 3 5-6"/>',building:'<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M8 6h1m6 0h1M8 10h1m6 0h1M8 14h1m6 0h1M10 22v-4h4v4"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z"/>',logout:'<path d="M9 4H3v16h6M13 8l5 4-5 4M8 12h13"/>',note:'<path d="M5 3h14v14l-4 4H5zM9 8h6M9 12h6M14 21v-5h5"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3h.01"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2M12 21v2M1 12h2M21 12h2M4 4l1 1M19 19l1 1M4 20l1-1M19 5l1-1"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z"/>'};
const icon=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.note}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dt=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'—';
const datetime=v=>v?new Date(THJournalCore.timestamp(v)).toLocaleString('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' WIB':'—';
const btn=(text,action,id='',cls='btn',ico='')=>`<button type="button" class="${cls}" data-action="${action}" aria-label="${esc(action==='view'?(id==='list'?'Tampilan daftar':'Tampilan papan'):action==='alerts'?'Buka pemberitahuan':String(text).replace(/<[^>]*>/g,'').trim()||action)}" ${id?`data-id="${esc(id)}"`:''}>${ico?icon(ico):''}${text}</button>`;
const badge=(text,color='neutral')=>`<span class="badge ${color}">${esc(text)}</span>`;
const empty=(title,sub='Belum ada data untuk pilihan ini.')=>`<div class="empty">${icon('note')}<h3>${title}</h3><p>${sub}</p></div>`;
const getEmp=id=>db.employees.find(e=>e.id===id)?.name||'Karyawan nonaktif';
const getTenant=id=>db.tenants.find(t=>t.id===id);
const actor=()=>window.THCloud?.state?.member.name|| (ui.role==='Owner'?'Owner Demo':ui.role==='Konsumen'?(getTenant(ui.consumer)?.name||'Konsumen Demo'):getEmp(ui.employee));
const dueFor=hours=>{return THJournalCore.local(new Date(Date.now()+Number(hours)*36e5).toISOString())};
const initials=name=>name.split(' ').slice(0,2).map(n=>n[0]).join('');
const statusColor=s=>s==='Selesai'||s.startsWith('Lunas')||s.startsWith('Terverifikasi')?'green':s.includes('Siap')?'blue':s==='Tertahan'?'red':s.includes('Verifikasi')?'yellow':'neutral';
const paid=o=>o.payment.startsWith('Lunas');
function toast(text){const e=document.querySelector('#toast');e.textContent=text;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),4200)}
function audit(text){db.audit.unshift({id:uid(),at:new Date().toISOString(),actor:actor(),text});}
function persist(message){if(window.THCloud)return THCloud.saveOps(message);try{localStorage.setItem(KEY,JSON.stringify(db));storageOK=true}catch(e){storageOK=false;message='Penyimpanan perangkat penuh atau dibatasi. Unduh cadangan sekarang; perubahan masih ada di sesi ini.';}render();if(message)toast(message);}
function canEdit(){if(window.THAccess&&!THAccess.current())throw Error('Masuk ke akun demo terlebih dahulu.');if(ui.role==='Konsumen')throw Error('Tindakan ini tersedia untuk petugas.');}
function ownerOnly(){if(window.THAccess&&THAccess.current()?.role!=='Owner')throw Error('Tindakan ini hanya tersedia untuk Owner.');if(ui.role!=='Owner')throw Error('Tindakan ini hanya tersedia untuk Owner.');}
function download(name,body,type='text/plain'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Teks disalin.')}catch{openModal('Salin teks ini',`<textarea rows="14" readonly id="copy-text">${esc(t)}</textarea><p class="muted">Pilih teks, lalu salin dengan Ctrl/Cmd + C.</p>`);document.querySelector('#copy-text').select();}}
function openModal(title,body,wide=false){dialog.innerHTML=`<div class="modal-head"><div><span class="eyebrow">TOP HILLS & CO</span><h2 id="dialog-title">${title}</h2></div><button class="icon-btn" data-action="close" aria-label="Tutup">${icon('close')}</button></div><div class="modal-body">${body}</div>`;dialog.className=wide?'wide':'';if(!dialog.open)dialog.showModal();}
function closeModal(){dialog.close();ui.selected=null;}
const field=(label,name,type='text',value='',extra='')=>type==='hidden'?`<input type="hidden" name="${name}" value="${esc(value)}" ${extra}>`:`<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,opts,value='',extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${opts.map(o=>{let [val,text]=Array.isArray(o)?o:[o,o];return `<option value="${esc(val)}" ${String(value)===String(val)?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`;
const area=(label,name,value='',extra='')=>`<label class="field span2"><span>${label}</span><textarea name="${name}" rows="3" ${extra}>${esc(value)}</textarea></label>`;
const check=(label,name,checked=false)=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}><span>${label}</span></label>`;
const formFoot=(text='Simpan',note='Semua data dalam aplikasi ini adalah simulasi.')=>`<p class="form-note">${note}</p><div class="form-error" role="alert"></div><div class="modal-actions">${btn('Batal','close','','btn ghost')}<button type="submit" class="btn primary">${icon('check')}${text}</button></div>`;
const tabs=(items)=>`<div class="tabs" role="tablist">${items.map(([v,l])=>`<button role="tab" aria-selected="${ui.tab===v}" class="${ui.tab===v?'active':''}" data-action="tab" data-id="${v}">${l}</button>`).join('')}</div>`;
const todayOrders=()=>db.orders.filter(o=>o.created.startsWith(ui.date));
const labelFor=o=>Array.from({length:o.bags},(_,i)=>`${o.id}-${String.fromCharCode(65+i)}/${o.bags}`).join(', ');
function render(){
if(window.THAccess){if(!THAccess.bind()){THAccess.render();return;}THAccess.cleanup();}
if(ui.role==='Konsumen'){renderConsumer();return;}
const nav=[['home','home','Jurnal usaha'],['operations','laundry','Operasional'],['finance','wallet','Laporan'],['guide','book','Buku panduan'],['team','users',ui.role==='Owner'?'Tim & evaluasi':'Laporan saya']].filter(n=>ui.role!=='Finance'||['home','finance','guide'].includes(n[0]));
app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-id="home"><span class="brand-name">top hills<span class="brand-star">✳</span></span><span class="brand-sub">& co. <i>jurnal usaha</i></span></a><div class="workspace-tag">${icon('building')}TOP HILLS · PADANG</div><nav>${nav.map(([p,ic,l])=>`<button class="nav-item ${ui.page===p?'active':''}" data-action="nav" data-id="${p}" aria-current="${ui.page===p?'page':'false'}">${icon(ic)}<span>${l}</span>${ui.page===p?'<span class="active-mark"></span>':''}</button>`).join('')}</nav><a class="nav-item" href="/laundry-desk">↗ Meja laundry & QR</a><div class="sidebar-note"><span class="hand">Sedikit demi sedikit,<br>semua jadi rapi.</span><span class="note-line"></span><p>Ruang kerja untuk layanan<br>yang lebih terjaga.</p></div><div class="sidebar-bottom">${ui.role==='Owner'?'<button class="nav-item" data-access="manage">'+icon('users')+'Akses akun</button>':''}${['Owner','Finance'].includes(ui.role)?btn('Cadangkan data','backup','','nav-item','download'):''}${ui.role==='Owner'?btn('Pengaturan','settings','','nav-item','settings'):''}<div class="local-status">${icon('shield')}<span>${window.THCloud?'Ruang kerja bersama':storageOK?'Tersimpan di perangkat':'Sesi sementara · cadangkan'}<small>${window.THCloud?'Data usaha':'Data fiktif'} · Top Hills</small></span></div></div></aside><div class="workspace"><header class="topbar">${btn(icon('list'),'workspace-menu','','icon-btn workspace-menu-button')}<div class="crumb"><span class="crumb-root">Ruang kerja</span><span>/</span> <strong>${nav.find(x=>x[0]===ui.page)?.[2]}</strong></div><div class="top-actions"><span class="demo-label">${window.THCloud?'Operasional':'Mode latihan'}</span>${btn(`${icon('bell')}<span class="notification-dot"></span>`,'alerts','','icon-btn','')}${window.THAccess?THAccess.widget():''}</div></header><main id="main" tabindex="-1">${ui.role==='Operator'?`<div class="operator-strip">${icon('users')}Bekerja sebagai <strong>${esc(getEmp(ui.employee))}</strong><span>Hanya Owner yang menilai dan memverifikasi setoran.</span></div>`:''}${ui.page==='home'?renderHome():ui.page==='operations'?renderOperations():ui.page==='finance'?THFinance.render():ui.page==='guide'?renderGuide():renderTeam()}</main><footer class="footer"><span>Top Hills & Co <span class="muted">/</span> a little more organized.</span><span>${window.THCloud?'Catatan usaha · akses sesuai peran.':'Seluruh nama, tarif, dan transaksi adalah fiktif.'}</span></footer></div><nav class="bottom-nav">${nav.map(([p,ic,l])=>`<button class="${ui.page===p?'active':''}" data-action="nav" data-id="${p}" aria-label="${l}">${icon(ic)}<span>${p==='home'?'Jurnal':p==='operations'?'Operasional':p==='guide'?'Panduan':p==='finance'?'Laporan':'Tim'}</span></button>`).join('')}</nav></div>`;
}
function renderHome(){const todays=todayOrders(),open=db.orders.filter(o=>!['Selesai','Dibatalkan'].includes(o.stage)),ready=open.filter(o=>o.stage==='Siap Diserahkan'),priority=open.filter(o=>alertFor(o,ui.date).level!=='green').sort((a,b)=>a.created.localeCompare(b.created));const finished=db.orders.filter(o=>o.stage==='Selesai'&&o.completed?.startsWith(ui.date)),pct=Math.round(finished.length/(open.length+finished.length||1)*100),collected=todays.filter(paid).reduce((s,o)=>s+o.total,0);const date=new Date(ui.date+'T12:00:00'),weekday=date.getDay()||7,start=dayShift(ui.date,1-weekday);
return `<div class="page-heading"><div><div class="eyebrow">${icon('sun')} ${date.toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}${window.THCloud?'':' · SIMULASI'}</div><h1>Jurnal hari ini<span class="heading-dot">.</span></h1><p>Halo, ${ui.role==='Owner'?'Owner':esc(getEmp(ui.employee).split(' ')[0])}. Yuk, lihat apa yang perlu dibereskan.</p></div>${btn('Tambah order','new-order','','btn primary','plus')}</div><div class="week-row"><span class="week-month hand">${date.toLocaleDateString('id-ID',{month:'long'})}<small>pilih hari jurnalmu</small></span><div class="week-strip">${Array.from({length:7},(_,i)=>{const d=dayShift(start,i),dd=new Date(d+'T12:00:00');return `<button data-action="date" data-id="${d}" aria-pressed="${d===ui.date}" class="day ${d===ui.date?'selected':''}"><span>${dd.toLocaleDateString('id-ID',{weekday:'short'})}</span><strong>${dd.getDate()}</strong><i>${db.orders.some(o=>o.created.startsWith(d))?'•':''}</i></button>`}).join('')}</div><button class="icon-btn" data-action="pick-date" aria-label="Pilih tanggal">${icon('book')}</button></div><div class="metric-grid">${metric('Order masuk',todays.length,'order di jurnal hari ini','laundry','blue')}${metric('Siap diserahkan',ready.length,'order menunggu di rak siap','check','green')}${metric('Tagihan dibuat',money(todays.reduce((s,o)=>s+o.total,0)),'nilai order masuk hari ini','note','yellow')}${metric('Dibayar · order hari ini',money(collected),'pembayaran customer tercatat','wallet','blue')}</div><div class="dashboard-grid"><section class="journal-panel"><div class="panel-heading"><h2>Di meja laundry <span class="count">${open.length}</span></h2>${btn('Lihat semua','goto','laundry','text-btn','arrow')}</div><div class="laundry-summary"><div class="progress-ring" style="--p:${pct}"><div><strong>${finished.length}<span> / ${open.length+finished.length}</span></strong><small>order beres</small></div></div><div class="laundry-summary-copy"><h3 class="hand">Satu cucian,<br>satu perhatian.</h3><p>${ready.length} order siap kembali<br>ke pemiliknya.</p></div><img class="basket" src="${basketSrc}" alt="Keranjang laundry krom berisi handuk putih dan pakaian biru" width="240" height="240"></div><div class="mini-progress">${[['Diterima Laundry','blue'],['Diproses','green'],['Siap Diserahkan','yellow']].map(([s,c])=>`<div><span><i class="shape ${c}"></i>${s==='Diterima Laundry'?'Diterima':s==='Siap Diserahkan'?'Siap diserahkan':s}</span><strong>${open.filter(o=>o.stage===s).length}</strong></div>`).join('')}</div><div class="order-list">${open.slice(0,4).map(o=>orderRow(o)).join('')}</div><button class="add-row" data-action="new-order">${icon('plus')} Catat laundry baru <span>Jemput atau antar langsung</span></button></section><aside class="right-stack"><section class="attention-paper"><div class="panel-heading"><h2>Perlu perhatian</h2><span class="tiny-hand">jangan terlewat!</span></div>${priority.length?priority.slice(0,3).map(o=>`<button class="attention-item" data-action="order" data-id="${o.id}"><span class="alert-icon ${alertFor(o,ui.date).level}">${icon('clock')}</span><div><strong>${esc(o.customer)} <span>· ${esc(o.room)}</span></strong><p>${o.checkout&&new Date(o.checkout)<=new Date(ui.date+'T12:00:00')?'Check-out hari ini / terlewat. Atur penyerahan.':alertFor(o,ui.date).label+' · '+o.stage}</p><small>${o.id} · ${esc(getEmp(o.pic).split(' ')[0])}</small></div>${icon('chevron')}</button>`).join(''):empty('Antrean dalam target','Belum ada order yang memerlukan eskalasi.')}<div class="attention-bottom">${icon('shield')}Mengikuti peringatan SOP 2 & 3 hari.</div></section><section class="team-paper"><div class="panel-heading"><h2>Catatan tim</h2>${btn('Buka','goto','reports','text-btn','arrow')}</div>${db.employees.filter(e=>e.active).map(e=>{const reports=db.reports.filter(r=>r.employeeId===e.id&&r.date===ui.date);return `<div class="team-mini"><span class="avatar ${e.color}">${initials(e.name)}</span><div><strong>${esc(e.name)}</strong><small>${esc(e.position)}</small></div>${reports.length?badge('Laporan masuk','green'):badge('Belum lapor','neutral')}</div>`}).join('')}<div class="paper-note">${icon('edit')}Aktivitas kecil hari ini, perbaikan untuk esok.</div></section></aside></div><section class="quick-note"><div>${icon('note')}<span class="hand">Ada yang perlu dicatat?</span></div><button data-action="new-report">Tulis aktivitas atau kendala hari ini… ${icon('plus')}</button></section>`;}
function metric(label,value,sub,ic,c){return `<div class="metric"><div class="metric-label">${label}<span class="metric-icon ${c}">${icon(ic)}</span></div><strong>${value}</strong><small>${sub}</small></div>`;}
function orderRow(o){return `<button class="order-row" data-action="order" data-id="${o.id}"><span class="order-symbol ${o.stage==='Siap Diserahkan'?'yellow':'blue'}">${icon(o.stage==='Siap Diserahkan'?'check':'laundry')}</span><div class="order-person"><strong>${esc(o.customer)}</strong><small>${o.id} <span>·</span> ${esc(THServices.location(o)||o.room||'Umum')} <span>·</span> ${esc(THServices.quantityText(o))}</small></div><div class="order-end">${badge(o.stage,statusColor(o.stage))}<small>${money(o.total)}</small></div>${icon('chevron')}</button>`;}
function renderOperations(){return `<div class="page-heading"><div><div class="eyebrow">RUANG KERJA HARIAN</div><h1>Operasional<span class="heading-dot">.</span></h1><p>Barang, penghuni, dan penerimaan tercatat dalam satu tempat.</p></div>${btn(ui.tab==='tenants'?'Tambah penghuni':ui.tab==='invoices'?'Buat tagihan':ui.tab==='closing'?'Closing cash':'Tambah order',ui.tab==='tenants'?'new-tenant':ui.tab==='invoices'?'new-invoice':ui.tab==='closing'?'new-settlement':'new-order','','btn primary','plus')}</div>${tabs([['laundry','Laundry'],['tenants','Penghuni'],['invoices','Tagihan'],['closing','Kas & setoran']])}${ui.tab==='tenants'?renderTenants():ui.tab==='invoices'?renderInvoices():ui.tab==='closing'?renderClosing():renderLaundry()}`;}
function renderLaundry(){let orders=db.orders.filter(o=>(ui.filter==='Semua'||ui.filter==='Prioritas'&&alertFor(o,ui.date).level!=='green'||ui.filter==='Belum lunas'&&!paid(o)||o.stage===ui.filter)&&`${o.id} ${o.customer} ${o.room} ${o.building||''} ${o.floor||''} ${o.roomType||''}`.toLowerCase().includes(ui.search.toLowerCase()));return `<div class="toolbar"><label class="search-box">${icon('search')}<input id="search" placeholder="Cari nama, kamar, atau nomor order" value="${esc(ui.search)}" aria-label="Cari order"></label><select id="order-filter" aria-label="Filter order">${['Semua','Prioritas','Belum lunas',...stages,'Tertahan','Dibatalkan'].map(s=>`<option ${ui.filter===s?'selected':''}>${s}</option>`).join('')}</select><div class="view-switch">${btn(icon('list'),'view','list',`icon-btn ${ui.view==='list'?'active':''}`)}${btn(icon('grid'),'view','board',`icon-btn ${ui.view==='board'?'active':''}`)}</div>${btn('Ekspor','export-orders','','btn ghost','download')}</div>${db.requests.filter(r=>r.status==='Baru').length?`<div class="notice blue">${icon('bell')}Ada ${db.requests.filter(r=>r.status==='Baru').length} permintaan customer yang perlu dicatat.${btn('Lihat permintaan','requests','','text-btn','arrow')}</div>`:''}<div id="order-results">${laundryResults(orders)}</div>`;}
function laundryResults(orders){if(!orders.length)return empty('Order tidak ditemukan','Coba nama, nomor, atau filter lain.');if(ui.view==='board')return `<div class="kanban">${[['Masuk',['Pesanan Masuk','Menunggu Dijemput','Sudah Dijemput','Diterima Laundry']],['Diproses',['Diproses']],['Siap & diantar',['Siap Diserahkan','Dalam Pengantaran']],['Selesai / tertahan',['Selesai','Tertahan','Dibatalkan']]].map(([label,ss])=>`<section><div class="kanban-head"><h3>${label}</h3><span>${orders.filter(o=>ss.includes(o.stage)).length}</span></div>${orders.filter(o=>ss.includes(o.stage)).map(o=>`<button class="kanban-card" data-action="order" data-id="${o.id}"><small>${o.id} · ${esc(THServices.location(o)||o.room)}</small><h3>${esc(o.customer)}</h3><p>${esc(THServices.quantityText(o))} · ${esc(o.package)}</p>${badge(o.stage,statusColor(o.stage))}<div>${money(o.total)}<span class="avatar small blue">${initials(getEmp(o.pic))}</span></div></button>`).join('')}</section>`).join('')}</div>`;return `<section class="paper table-wrap"><table><thead><tr><th>Order / customer</th><th>Layanan</th><th>Status barang</th><th>Pembayaran</th><th>Target / prioritas</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${esc(o.customer)}</strong><small>${o.id} · ${esc(THServices.location(o)||o.room||'Umum')}</small></td><td>${esc(THServices.quantityText(o))}<small>${esc(o.package)} · ${money(o.total)}</small></td><td>${badge(o.stage,statusColor(o.stage))}<small>${esc(getEmp(o.pic))}</small></td><td>${badge(o.payment,statusColor(o.payment))}<small>${esc(o.method)}</small></td><td>${datetime(o.due)}<small class="text-${alertFor(o,ui.date).level}">${alertFor(o,ui.date).label}</small></td><td>${btn('Detail','order',o.id,'btn small')}</td></tr>`).join('')}</tbody></table><div class="table-footer">${orders.length} order · status barang, pembayaran, dan settlement dicatat terpisah.</div></section>`;}
function renderTenants(){const active=db.tenants.filter(t=>t.status==='Aktif');return `<div class="metric-grid three">${metric('Pelanggan hunian aktif',active.length,'kost & penginapan','users','blue')}${metric('Kamar terisi',new Set(active.map(t=>[t.building,t.floor,t.room].join('|'))).size,'berdasarkan data pelanggan aktif','building','yellow')}${metric('Checkout dekat',active.filter(t=>t.end>=ui.date&&t.end<=dayShift(ui.date,3)).length,'dalam 3 hari','clock','green')}</div><section class="paper table-wrap"><table><thead><tr><th>Pelanggan / kontak</th><th>Lokasi & kamar</th><th>Jenis hunian</th><th>Checkout / akhir tinggal</th><th>Status</th><th></th></tr></thead><tbody>${db.tenants.map(t=>`<tr><td><strong>${esc(t.name)}</strong><small>${esc(t.contact)}</small></td><td>${esc(THServices.location(t))}<small>${esc(t.roomType||'Jenis kamar belum diisi')}</small></td><td>${esc(t.type)}${t.laundryOnly?'<small>Data sewa belum lengkap</small>':''}</td><td>${t.checkout?datetime(t.checkout):t.end?dt(t.end):'Belum diisi'}</td><td>${badge(t.status,t.status==='Aktif'?'green':'neutral')}</td><td>${btn('Kelola','tenant',t.id,'btn small')}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada pelanggan hunian. Tambahkan langsung saat membuat order.</td></tr>'}</tbody></table></section>`;}
function renderInvoices(){const outstanding=db.invoices.reduce((s,i)=>s+i.amount-i.paid,0),received=db.invoices.reduce((s,i)=>s+i.paid,0);return `<div class="metric-grid three">${metric('Sisa tagihan hunian',money(outstanding),'total yang belum dicatat lunas','wallet','yellow')}${metric('Penerimaan hunian',money(received),'akumulasi pembayaran demo','check','green')}${metric('Jatuh tempo',db.invoices.filter(i=>i.paid<i.amount&&i.due<=ui.date).length,'tagihan perlu ditindaklanjuti','clock','blue')}</div><section class="paper"><div class="panel-heading"><h2>Collection hunian</h2>${btn('Ekspor','export-invoices','','text-btn','download')}</div><div class="table-wrap"><table><thead><tr><th>Tagihan</th><th>Total / diterima</th><th>Sisa</th><th>Jatuh tempo</th><th></th></tr></thead><tbody>${db.invoices.map(i=>`<tr><td><strong>${esc(getTenant(i.tenantId)?.name||'Penghuni diarsipkan')}</strong><small>${i.id} · ${esc(i.title)}</small></td><td>${money(i.amount)}<small>Diterima ${money(i.paid)}</small></td><td>${i.paid===i.amount?badge('Lunas','green'):money(i.amount-i.paid)}</td><td>${dt(i.due)}${i.paid<i.amount&&i.due<=ui.date?'<small class="text-red">Perlu follow-up</small>':''}</td><td>${btn('Rincian','invoice',i.id,'btn small')}</td></tr>`).join('')}</tbody></table></div></section><section class="paper section-gap"><div class="panel-heading"><h2>Pembayaran laundry</h2><span class="muted">Terpisah dari tagihan hunian</span></div>${db.orders.filter(o=>!paid(o)&&o.stage!=='Dibatalkan').map(orderRow).join('')||empty('Semua pembayaran tercatat')}</section>`;}
function renderClosing(){const cash=window.THCloud?THCloud.state.finance.transactions.filter(t=>t.kind==='receipt'&&t.method==='Cash'&&t.status==='Tercatat'&&!t.fixture):db.orders.filter(o=>o.payment==='Lunas Cash'),unbatched=cash.filter(o=>!o.settlementId),total=unbatched.reduce((s,o)=>s+(o.amount??o.total),0);const dates=db.orders.filter(o=>o.created.startsWith(ui.date));return `<div class="notice blue">${icon('shield')}Lunas Cash berarti pelanggan sudah membayar. Setoran baru terverifikasi setelah Owner mencocokkan mutasi.</div><div class="metric-grid three">${metric('Cash belum closing',money(total),unbatched.length+' kuitansi belum masuk settlement','wallet','yellow')}${metric('Menunggu verifikasi',db.settlements.filter(s=>s.status==='Sudah Disetor').length,'setoran membutuhkan Owner','shield','blue')}${metric('Selisih terbuka',money(db.settlements.filter(s=>!s.resolved).reduce((n,s)=>n+Math.abs(s.difference),0)),'selisih tetap disimpan dalam audit','alert','green')}</div><section class="paper"><div class="panel-heading"><h2>Settlement cash</h2><span class="hand">setor utuh, catat terpisah</span></div>${db.settlements.length?`<div class="table-wrap"><table><thead><tr><th>Settlement</th><th>Wajib setor / fisik</th><th>Selisih</th><th>Status</th><th></th></tr></thead><tbody>${db.settlements.map(s=>`<tr><td><strong>${s.id}</strong><small>${s.orderIds.length} order · Saksi ${esc(s.witness)}</small></td><td>${money(s.expectedDeposit)}<small>Setoran fisik ${money(s.deposit)}</small></td><td class="${s.difference?'text-red':''}">${money(s.difference)}</td><td>${badge(s.status,statusColor(s.status))}</td><td>${btn('Buka','settlement',s.id,'btn small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada settlement','Mulai closing untuk menghitung cash, mencatat saksi, amplop, dan segel.')}</section><div class="two-columns section-gap"><section class="paper"><div class="panel-heading"><h2>Closing harian</h2>${btn('Salin rekap','copy-closing','','text-btn','copy')}</div><p class="muted">Jurnal ${dt(ui.date)} · paling lambat ${db.settings.closingMinutes} menit setelah tutup.</p><dl class="summary-list"><div><dt>Order masuk / volume</dt><dd>${dates.length} / ${dates.reduce((n,o)=>n+o.weight,0).toFixed(1)} kg</dd></div><div><dt>Tagihan dibuat</dt><dd>${money(dates.reduce((n,o)=>n+o.total,0))}</dd></div><div><dt>QRIS / transfer terverifikasi</dt><dd>${money(dates.filter(o=>o.payment==='Lunas Terverifikasi').reduce((n,o)=>n+o.total,0))}</dd></div><div><dt>Cash belum closing</dt><dd>${money(total)}</dd></div><div><dt>Label berikut / batas rentang</dt><dd>${db.settings.labelNext} / ${db.settings.labelEnd}</dd></div><div><dt>Kuitansi berikut / batas</dt><dd>${db.settings.receiptNext} / ${db.settings.receiptEnd}</dd></div></dl><p class="form-note">Nilai order mengikuti tanggal jurnal. Penerimaan cash yang belum closing dihitung lintas tanggal agar tidak terlewat.</p></section><section class="paper"><div class="panel-heading"><h2>Checklist rekonsiliasi</h2></div>${['Jejak customer cocok dengan order','Label dan paket pada rak cocok','Bukti timbang lengkap','Kuitansi cocok dengan cash diterima','Order selesai memiliki konfirmasi customer','Order prioritas memiliki PIC dan tindak lanjut'].map((s,i)=>`<label class="check daily-check"><input type="checkbox" data-daily-check="${i}" ${db.settings.checklist[ui.date+'-'+i]?'checked':''}><span>${s}</span></label>`).join('')}<p class="form-note">Checklist tersimpan per tanggal jurnal. Tidak menggantikan bukti independen.</p></section></div>`;}
const policies=[
['01','Penerimaan & identitas','Satu order, satu identitas yang mengikuti barang.',[['Label','Gunakan nomor berurutan dari rentang Owner. Nomor tidak diulang atau direset harian. Beberapa kantong memakai suffix A/2, B/2.'],['Antar langsung','Jejak check-in resmi, label, pencatatan, foto label bersama angka timbangan, lalu resi sebelum customer meninggalkan counter.'],['Jemput','Pesan nomor sebelum berangkat. Label dipasang sebelum barang dibawa. Simpan foto kantong dan konfirmasi SUDAH DIJEMPUT.'],['Layanan berbeda','Paket atau target selesai berbeda memerlukan order terpisah. Layanan per item dan barang khusus harus diperiksa; jangan otomatis dihitung kilogram.']]],
['02','Proses & penyerahan','Bukti lengkap sebelum melanjutkan tahap.',[['Mulai proses','Jejak customer, label, data, bukti timbang dan resi wajib lengkap. Jangan mencampur order tanpa kantong jaring berlabel.'],['Quality control','Cek identitas, jumlah kantong, layanan, kekeringan, kerapian, catatan khusus, dan risiko check-out.'],['Serah terima','Catat penerima dan waktu. Order selesai hanya setelah konfirmasi customer; titip ke pihak lain harus dengan izin tertulis.'],['Peringatan','Oranye saat umur order 2 hari atau target berisiko lewat. Merah saat 3 hari atau check-out tercapai. Setelah selesai, umur aktif nol; durasi historis tetap ada.']]],
['03','Pembayaran & cash','Dana customer dan settlement internal terpisah.',[['Noncash','QRIS resmi menjadi pilihan utama. Screenshot bukan bukti lunas: cocokkan mutasi rekening/merchant resmi.'],['Cash','Harus ada tagihan final dan kuitansi dua rangkap bernomor. Cash saat jemput awal sebelum timbang tidak diperbolehkan.'],['Cash di kamar','Hanya saat pengembalian laundry selesai, memakai kuitansi yang dialokasikan, konfirmasi customer, dan pouch bersegel.'],['Setor utuh','Cash laundry tidak boleh dipakai untuk biaya, kasbon, atau refund. Pisahkan petty cash. Lunas Cash tetap berlaku walau setoran belum diverifikasi.']]],
['04','Closing, settlement & audit','Setiap selisih terlihat dan bisa ditindaklanjuti.',[['Rumus','Cash fisik yang diharapkan = float + kuitansi sah. Wajib setor = kuitansi sah. Selisih = fisik − float − kuitansi. Target Rp0.'],['Tenggat','Closing maksimal 30 menit setelah tutup. Setor hari yang sama atau maksimal 10.00 hari kerja berikutnya; parameter perlu disahkan Owner.'],['Bukti & saksi','Hitung ulang bersama saksi, catat nomor amplop/segel, simpan terkunci, catat bukti setor. Owner mencocokkan mutasi sebelum verifikasi.'],['Audit','Minimal 3 sampel customer per minggu, termasuk kontrol cash. Dua kejadian berulang dalam 30 hari memicu peninjauan kewenangan. Selisih tetap dicatat walaupun penyebab diketahui.']]],
['05','Koreksi, pengecualian & akses','Jejak perubahan harus dapat ditelusuri.',[['Koreksi','Simpan nilai lama, baru, alasan, waktu, pengubah, dan bukti. Perubahan uang, pembatalan bertagihan, diskon dan refund perlu persetujuan Owner.'],['Tertahan','Barang tanpa label, bukti timbang hilang, perselisihan berat, kerusakan atau kehilangan ditahan dengan alasan, PIC, dan tindak lanjut.'],['Customer tanpa WA','Pengecualian berupa kuitansi manual dua rangkap bernomor, bukti timbang, tracker dan CCTV counter; ungkapkan saat closing.'],['Kontrol akses','Owner menguasai akun resmi dan verifikasi. Operator mencatat pekerjaan; tidak boleh memverifikasi settlement sendiri. Konsumen tidak melihat tracker internal.']]]
];
const templateNames=['Permintaan jemput','Konfirmasi jemput','Check-in antar langsung','Resi setelah timbang','Pemberitahuan siap','Konfirmasi serah terima','Petunjuk pembayaran','Konfirmasi cash','Closing cash','Bukti setoran','Verifikasi Owner','Serah terima shift','Pemberitahuan counter','Status internal','Closing harian'];
function templateText(i,o=db.orders[0]){const s=db.settlements[0];return [
`Halo Top Hills Laundry, saya ingin laundry dijemput.\nNama: ${o.customer}\nGedung/kamar/alamat: ${o.room}\nJumlah kantong: ${o.bags}\nWaktu tersedia: [isi waktu]\nPengembalian: ${o.returnMode}\nCatatan barang khusus: [isi catatan]`,
`Pesanan laundry sudah dicatat.\nNomor: ${o.id}\nLokasi jemput: ${o.room}\nPerkiraan: [tanggal dan jam]\nPetugas memasang label sebelum membawa barang. Mohon balas SUDAH DIJEMPUT setelah barang diterima petugas.`,
`Saya menyerahkan laundry ke counter Top Hills.\nNama: ${o.customer}\nStatus: ${o.type}\nKamar/alamat: ${o.room}\nWA demo: ${o.contact}\nKantong: ${o.bags}\nPengembalian: ${o.returnMode}`,
`TOP HILLS LAUNDRY · RESI DEMO\n${o.id}\nNama/kamar: ${o.customer} · ${o.room}\nMasuk: ${datetime(o.created)}\nJumlah: ${THServices.quantityText(o)}\nKantong: ${o.bags}\nPaket: ${o.package}\nTarif: ${money(o.rate)} / ${THServices.snapshot(o).unit}\nTotal: ${money(o.total)}\nPembayaran: ${o.payment}\nTarget: ${datetime(o.due)}\nPengembalian: ${o.returnMode}\nMohon periksa dan sampaikan koreksi sebelum diproses.`,
`Order ${o.id} siap diserahkan.\nPembayaran: ${o.payment}\nPilihan: ${o.returnMode}.\n${o.checkout?'Penyerahan sebelum check-out: '+datetime(o.checkout):'Silakan konfirmasi waktu pengambilan.'}`,
`Order ${o.id} diserahkan pada [tanggal dan jam].\nPenerima: ${o.recipient||'[nama penerima]'}\nMohon balas DITERIMA jika laundry sudah di tangan Anda, atau KOREKSI jika ada ketidaksesuaian.`,
`Utamakan QRIS resmi Top Hills Laundry.\nTransfer hanya ke rekening resmi; cantumkan ${o.id}.\nJika cash, minta kuitansi bernomor dan konfirmasi nominal.\nStatus noncash lunas setelah mutasi cocok. Jangan membayar ke akun pribadi petugas.\nDEMO: tidak ada kanal pembayaran aktif dalam aplikasi ini.`,
`Pembayaran cash ${o.id} sebesar ${money(o.total)} telah diterima pada [tanggal dan jam].\nNomor kuitansi: ${o.receipt||'[nomor kuitansi resmi]'}\nMohon balas BENAR atau KOREKSI jika nominal tidak sesuai.`,
`SETTLEMENT CASH · ${s?.id||'[ID settlement]'}\nFloat: ${money(s?.float||db.settings.float)}\nPenerimaan: ${money(s?.expectedDeposit||0)}\nFisik: ${money(s?.physical||0)}\nSelisih: ${money(s?.difference||0)}\nAmplop/segel: ${s?.envelope||'[amplop]'} / ${s?.seal||'[segel]'}\nSaksi: ${s?.witness||'[nama saksi]'}\n${s?'Status: '+s.status:'Lengkapi dari form closing sebelum digunakan.'}`,
`SETORAN CASH\nSettlement: ${s?.id||'[ID]'}\nJumlah: ${money(s?.deposit||0)}\nTanggal/jam: ${s?.depositAt?datetime(s.depositAt):'[isi]'}\nTujuan: rekening resmi Top Hills (demo)\nPetugas: ${s?.depositor||'[nama]'}\nBukti: ${s?.depositRef||'[referensi]'}\nStatus: ${s?.status||'BELUM ADA DATA'}`,
`VERIFIKASI OWNER\nSettlement: ${s?.id||'[ID]'}\nMutasi: ${s?.bankReference||'[referensi mutasi]'}\nStatus: ${s?.status||'BELUM TERVERIFIKASI'}\nSelisih: ${money(s?.difference||0)}\nCatatan: ${s?.note||'[isi tindak lanjut]'}`,
`SERAH TERIMA SHIFT CASH\nTanggal/jam: [isi]\nFloat: ${money(db.settings.float)}\nCash belum disetor: [isi]\nKuitansi terakhir: CSH-${String(db.settings.receiptNext-1).padStart(4,'0')}\nAmplop/segel: [isi]\nSelisih: [isi]\nDiserahkan oleh: [nama]\nDiterima oleh: [nama]\nHitung dan tandatangani bersama sebelum petugas lama pergi.`,
`UNTUK KEAMANAN LAUNDRY ANDA\n1. Lakukan check-in melalui WA resmi.\n2. Pastikan setiap kantong memiliki nomor order.\n3. Tunggu resi WA sebelum meninggalkan counter.\n4. Utamakan QRIS resmi.\n5. Jika cash, minta kuitansi bernomor dan konfirmasi nominal.\n6. Jangan membayar ke rekening/QRIS/nomor pribadi petugas.\n7. Laundry resmi diterima setelah resi bernomor dikirim.`,
`${o.id} | ${o.stage} | ${datetime(o.created)} | ${o.room} | ${o.bags} kantong | ${getEmp(o.pic)} | ${o.note||'[catatan singkat]'} | [bukti sesuai tahap]`,closingText()
][i];}
function closingText(){const os=todayOrders(),sum=p=>os.filter(p).reduce((s,o)=>s+o.total,0);return `CLOSING LAUNDRY DEMO · ${dt(ui.date)}\nJemput masuk: ${os.filter(o=>o.mode==='Jemput').length}\nAntar langsung: ${os.filter(o=>o.mode==='Antar langsung').length}\nTotal kg: ${os.reduce((s,o)=>s+o.weight,0).toFixed(1)}\nTagihan dibuat: ${money(sum(()=>true))}\nQRIS terverifikasi: ${money(sum(o=>o.payment==='Lunas Terverifikasi'&&o.method==='QRIS'))}\nTransfer terverifikasi: ${money(sum(o=>o.payment==='Lunas Terverifikasi'&&o.method==='Transfer'))}\nCash diterima (order tanggal ini): ${money(sum(o=>o.payment==='Lunas Cash'))}\nBelum bayar / belum verifikasi: ${money(sum(o=>!paid(o)))}\nCash lintas tanggal belum closing: ${money(db.orders.filter(o=>o.payment==='Lunas Cash'&&!o.settlementId).reduce((s,o)=>s+o.total,0))}\nSiap belum diserah (semua): ${db.orders.filter(o=>o.stage==='Siap Diserahkan').length}\nTertahan: ${db.orders.filter(o=>o.stage==='Tertahan').map(o=>o.id).join(', ')||'—'}\nOranye: ${db.orders.filter(o=>alertFor(o,ui.date).level==='orange').map(o=>o.id).join(', ')||'—'}\nMerah: ${db.orders.filter(o=>alertFor(o,ui.date).level==='red').map(o=>o.id).join(', ')||'—'}\nLabel berikut: ${db.settings.labelNext}\nKuitansi berikut: ${db.settings.receiptNext}\nSelisih terbuka: ${db.settlements.filter(s=>s.difference&&!s.resolved).map(s=>s.id+' '+money(s.difference)).join('; ')||'—'}\nCocokkan kembali dengan bukti customer, rak, kuitansi, dan mutasi. Rekap ini adalah simulasi lokal.`;}
function renderGuide(){return `<div class="page-heading"><div><div class="eyebrow">PEGANGAN BERSAMA</div><h1>Buku panduan<span class="heading-dot">.</span></h1><p>Aturan yang jelas, alur yang bisa diikuti, pesan yang siap dipakai.</p></div>${badge('SOP v0.2 + akses v0.3','blue')}</div>${tabs([['rules','Aturan & SOP'],['flow','Alur bisnis'],['templates','Template pesan']])}${ui.tab==='flow'?renderFlow():ui.tab==='templates'?`<div class="notice">${icon('copy')}Template diisi dari order demo pilihan. Salin dan tinjau teks; tidak ada pesan yang dikirim otomatis.</div><div class="template-grid">${templateNames.map((n,i)=>`<button class="template-card" data-action="template" data-id="${i}"><span class="template-number">${String(i+1).padStart(2,'0')}</span><h3>${n}</h3><p>${i<8?'Komunikasi customer':i<12?'Kontrol internal':'Operasional harian'}</p><span class="text-btn">Buka template ${icon('arrow')}</span></button>`).join('')}</div>`:`<div class="notice blue">${icon('book')}Alur laundry berdasarkan THL SOP OPS 001 v0.2; pengelolaan akses mengikuti ketentuan tambahan v0.3. Parameter harga, jam kerja, hunian, dan evaluasi tim adalah pengembangan demo; pengesahan SOP tetap oleh Owner.</div><section class="paper section-gap"><h2>Akun individual, akses terarah.</h2><p>Petugas menggunakan akun sendiri. Owner meninjau penambahan, perubahan, penonaktifan, dan tinjauan akses. Konsumen tidak mengakses pencatatan internal.</p><p class="muted">Akun dinonaktifkan tanpa menghapus riwayat. Pada website ini, login memakai akun ChatGPT. Owner menetapkan peran dan menautkan profil setelah pengguna memperoleh akses situs. Peran yang tersedia: Owner, Finance, Operator, dan Konsumen.</p></section><div class="policy-list">${policies.map(([n,title,desc,rows],idx)=>`<details class="policy" ${idx===0?'open':''}><summary><span class="policy-number">${n}</span><div><h2>${title}</h2><p>${desc}</p></div>${icon('down')}</summary><dl>${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl></details>`).join('')}</div><section class="paper section-gap"><div class="panel-heading"><h2>Alokasi bisnis & tanggung jawab</h2></div><div class="table-wrap"><table><thead><tr><th>Area</th><th>Operator / manajer</th><th>Owner</th><th>Customer</th></tr></thead><tbody><tr><td>Laundry</td><td>Terima, label, timbang, proses, QC, serah</td><td>Harga, pengecualian, audit</td><td>Permintaan, cek resi, konfirmasi</td></tr><tr><td>Hunian & collection</td><td>Data tinggal, tagihan, catat pembayaran</td><td>Kebijakan dan pemeriksaan</td><td>Lihat tagihan sendiri</td></tr><tr><td>Cash & closing</td><td>Hitung dengan saksi, segel, setor</td><td>Cocokkan mutasi, verifikasi, selisih</td><td>Kuitansi & konfirmasi nominal</td></tr><tr><td>Tim & laporan</td><td>Aktivitas global/laundry per hari</td><td>Kelola karyawan, feedback, skor</td><td>Tidak mengakses data internal</td></tr></tbody></table></div></section><section class="paper section-gap"><h2>Belum ditetapkan dalam SOP ini</h2><p class="muted">Formula cuci, penanganan noda, kompensasi, pengadaan stok, perawatan mesin, promo, dan detail petty cash memerlukan SOP lanjutan. Aplikasi tidak menganggap kebijakan tersebut sudah disahkan.</p>${btn('Baca isi SOP sumber','source-sop','','btn','book')}</section>`}`;}
function renderFlow(){return `<div class="flow-intro"><h2>Dua pintu masuk, satu rantai bukti.</h2><p>Setiap langkah mencatat siapa, kapan, dan bukti yang mendukungnya.</p></div><div class="two-columns"><section class="paper flow-path blue-top"><span class="eyebrow">JALUR 01</span><h2>Customer minta dijemput</h2>${[['Permintaan resmi','Identitas, lokasi, kantong, waktu dan pilihan kembali.'],['Alokasikan label & petugas','Nomor dipesan sebelum petugas berangkat.'],['Label di titik jemput','Foto kantong berlabel + balasan SUDAH DIJEMPUT.']].map(([a,b],i)=>flowStep(i+1,a,b)).join('')}</section><section class="paper flow-path yellow-top"><span class="eyebrow">JALUR 02</span><h2>Antar langsung ke counter</h2>${[['Check-in resmi','Jejak customer dari check-in ke WA resmi.'],['Label sebelum masuk area kerja','Cek kantong dan barang khusus, pasang nomor berurutan.'],['Timbang & kirim resi','Foto label dan angka timbangan; customer memeriksa resi.']].map(([a,b],i)=>flowStep(i+1,a,b)).join('')}</section></div><section class="paper section-gap"><div class="panel-heading"><h2>Proses bersama</h2>${btn('Coba buat order','new-order','','text-btn','arrow')}</div><div class="flow-shared">${[['Penerimaan sah','Label + data + bukti timbang + resi'],['Proses & QC','PIC, pemisahan, cek barang, kemas'],['Siap & serah','Jadwalkan sebelum check-out'],['Konfirmasi selesai','Nama penerima + waktu + bukti customer']].map(([a,b],i)=>flowStep(i+4,a,b)).join('')}</div></section><div class="two-columns section-gap"><section class="paper"><h2>Pembayaran customer</h2><p><b>QRIS / transfer:</b> bukti → menunggu verifikasi → mutasi cocok → lunas terverifikasi.</p><p><b>Cash:</b> tagihan final → kuitansi resmi → customer lunas cash.</p></section><section class="paper"><h2>Settlement internal</h2><p>Hitung bersama saksi → catat selisih → segel → setor utuh → cocokkan mutasi oleh Owner.</p><p class="hand">Customer lunas ≠ setoran terverifikasi.</p></section></div>`;}
function flowStep(i,a,b){return `<div class="flow-step"><span>${i}</span><div><h3>${a}</h3><p>${b}</p></div></div>`;}
function renderTeam(){if(ui.role==='Operator')ui.tab='reports';return `<div class="page-heading"><div><div class="eyebrow">ORANG-ORANG DI BALIK LAYANAN</div><h1>${ui.role==='Owner'?'Tim & evaluasi':'Laporan saya'}<span class="heading-dot">.</span></h1><p>Catat kontribusi, bicarakan hambatan, dan tentukan perbaikan.</p></div>${btn(ui.tab==='members'?'Tambah karyawan':ui.tab==='evaluations'?'Beri penilaian':'Tulis laporan',ui.tab==='members'?'new-employee':ui.tab==='evaluations'?'new-evaluation':'new-report','','btn primary','plus')}</div>${ui.role==='Owner'?tabs([['members','Anggota tim'],['reports','Laporan harian'],['evaluations','Penilaian Owner'],['audit','Jejak aktivitas']]):''}${ui.tab==='members'?renderMembers():ui.tab==='evaluations'?renderEvaluations():ui.tab==='audit'?renderAudit():renderReports()}`;}
function renderMembers(){return `<div class="employee-grid">${db.employees.map(e=>{const rs=db.reports.filter(r=>r.employeeId===e.id),evs=db.evaluations.filter(v=>v.employeeId===e.id),avg=evs.length?(evs.reduce((s,v)=>s+v.scores.reduce((n,x)=>n+x,0)/6,0)/evs.length).toFixed(1):'—';return `<section class="employee-card"><div class="employee-card-top"><span class="avatar large ${e.color}">${initials(e.name)}</span>${badge(e.active?'Aktif':'Nonaktif',e.active?'green':'neutral')}</div><h2>${esc(e.name)}</h2><p>${esc(e.position)}</p><span class="muted">${esc(e.division)}</span><div class="employee-stats"><div><strong>${rs.length}</strong><span>Laporan</span></div><div><strong>${avg}<small> / 5</small></strong><span>Rata-rata skor</span></div></div><div class="button-row">${btn('Edit profil','employee',e.id,'btn','edit')}${btn(e.active?'Nonaktifkan':'Aktifkan','employee-toggle',e.id,'text-btn')}</div></section>`}).join('')}</div><p class="form-note">Menonaktifkan karyawan menghapusnya dari pilihan petugas aktif. Laporan, penilaian, dan audit tetap tersimpan.</p>`;}
function renderReports(){const rs=db.reports.filter(r=>ui.role==='Owner'||r.employeeId===ui.employee).filter(r=>!ui.search||`${getEmp(r.employeeId)} ${r.activity} ${r.division} ${r.date}`.toLowerCase().includes(ui.search.toLowerCase()));return `<div class="toolbar"><label class="search-box">${icon('search')}<input id="report-search" placeholder="Cari nama, tanggal, global atau laundry" value="${esc(ui.search)}" aria-label="Cari laporan"></label>${btn('Ekspor laporan','export-reports','','btn ghost','download')}</div><div class="report-grid">${rs.length?rs.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<section class="report-card"><div class="report-top"><div><strong>${esc(getEmp(r.employeeId))}</strong><small>${dt(r.date)} · ${r.hours} jam</small></div>${badge(r.division,r.division==='Laundry'?'blue':'yellow')}</div><h3>${esc(r.activity)}</h3><p>${esc(r.output)}</p>${r.obstacle?`<div class="report-obstacle">${icon('alert')}${esc(r.obstacle)}</div>`:''}<div class="report-bottom">${badge(r.status,statusColor(r.status==='Ditinjau'?'Selesai':r.status))}${btn('Baca laporan','report',r.id,'text-btn','arrow')}</div></section>`).join(''):empty('Belum ada laporan','Catat pekerjaan, hasil, hambatan, dan rencana berikutnya.')}</div>`;}
function renderEvaluations(){return `<div class="notice blue">${icon('star')}Skor 1–5 berdasarkan bukti aktivitas, disertai feedback dan rencana perbaikan. “Lingkungan kerja” menilai dukungan/kondisi kerja, bukan karakter pribadi.</div><div class="score-legend">${[['1','Perlu pendampingan'],['2','Belum konsisten'],['3','Sesuai harapan'],['4','Konsisten baik'],['5','Melampaui harapan']].map(([n,t])=>`<span><b>${n}</b>${t}</span>`).join('')}</div>${db.evaluations.length?`<div class="evaluation-list">${db.evaluations.map(v=>`<section class="paper"><div class="panel-heading"><div><h2>${esc(getEmp(v.employeeId))}</h2><p class="muted">${dt(v.date)} · dinilai Owner</p></div><strong class="overall-score">${(v.scores.reduce((n,x)=>n+x,0)/6).toFixed(1)}<small>/5</small></strong></div><div class="score-grid">${scoreKeys.map((k,i)=>`<div><span>${k}</span><strong>${v.scores[i]} / 5</strong><progress max="5" value="${v.scores[i]}"></progress></div>`).join('')}</div><p><b>Bukti:</b> ${esc(v.evidence)}</p><p><b>Feedback:</b> ${esc(v.feedback)}</p><p><b>Langkah berikut:</b> ${esc(v.next)}</p>${btn('Perbarui penilaian','evaluation',v.id,'text-btn','edit')}</section>`).join('')}</div>`:empty('Penilaian pertama dimulai dari bukti','Pilih karyawan dan tanggal, lalu nilai enam aspek beserta feedback.')}`;}
function renderAudit(){return `<section class="paper"><div class="panel-heading"><h2>Riwayat perubahan</h2>${btn('Ekspor audit','export-audit','','text-btn','download')}</div><div class="audit-list">${db.audit.map(a=>`<div>${icon('clock')}<div><strong>${esc(a.text)}</strong><small>${datetime(a.at)} · ${esc(a.actor)}</small></div></div>`).join('')}</div></section>`;}
function renderConsumer(){const t=getTenant(ui.consumer);if(!t){app.innerHTML=`<div class="access-pending"><div class="brand-name">top hills✳</div>${window.THAccess?THAccess.widget():''}<h1>Akun Anda sudah tersimpan.</h1><p>Owner perlu menautkan akun ini ke profil pelanggan sebelum laundry dan tagihan dapat ditampilkan.</p></div>`;return;}ui.consumer=t.id;const os=db.orders.filter(o=>o.tenantId===t.id),invs=db.invoices.filter(i=>i.tenantId===t.id);app.innerHTML=`<div class="consumer-app"><header class="consumer-header"><a class="brand" href="#"><span class="brand-name">top hills<span class="brand-star">✳</span></span><span class="brand-sub">& co. <i>your little living journal</i></span></a>${window.THAccess?THAccess.widget():''}</header><main><div class="consumer-greeting"><div><span class="eyebrow">RUANG PENGHUNI · ${esc(t.room)}</span><h1>Halo, ${esc(t.name.split(' ')[0])}<span class="heading-dot">.</span></h1><p>Laundry dan catatan tinggalmu, di sini.</p></div><img src="${basketSrc}" width="200" height="200" alt="Keranjang laundry dengan pakaian terlipat"></div><div class="notice">${icon('shield')}Pembayaran diverifikasi petugas. Pesan WhatsApp dikirim secara manual.</div><div class="two-columns"><section class="paper"><div class="panel-heading"><h2>Laundry saya</h2>${btn('Minta jemput','consumer-request','','btn primary','plus')}</div>${os.map(o=>`<div class="consumer-order"><small>${o.id} · ${esc(THServices.quantityText(o))}</small><div><h3>${esc(o.package)}</h3>${badge(o.stage,statusColor(o.stage))}</div><p>Target ${datetime(o.due)}</p><div class="consumer-order-bottom"><span>${money(o.total)} · ${esc(o.payment)}</span>${btn('Lihat resi','consumer-order',o.id,'text-btn','arrow')}</div></div>`).join('')||empty('Belum ada laundry')}${db.requests.filter(r=>r.tenantId===t.id).map(r=>`<div class="notice blue">${icon('note')}Permintaan ${r.bags} kantong · ${esc(r.status)} · ${esc(r.time)}</div>`).join('')}</section><aside class="right-stack"><section class="paper yellow-top"><span class="eyebrow">CATATAN TINGGAL</span><h2 class="hand">Rumah kecilmu di Top Hills.</h2><dl class="summary-list"><div><dt>Kamar / gedung</dt><dd>${esc(THServices.location(t))}<small>${esc(t.roomType||'')}</small></dd></div><div><dt>Jenis hunian</dt><dd>${esc(t.type)}</dd></div><div><dt>Akhir masa tinggal</dt><dd>${dt(t.end)}</dd></div></dl></section><section class="paper"><div class="panel-heading"><h2>Tagihan saya</h2></div>${invs.map(i=>`<div class="invoice-mini"><strong>${esc(i.title)}</strong><p>Jatuh tempo ${dt(i.due)}</p><div>${money(i.amount-i.paid)} ${badge(i.amount===i.paid?'Lunas':'Sisa tagihan',i.amount===i.paid?'green':'yellow')}</div></div>`).join('')||empty('Tidak ada tagihan')}</section></aside></div></main><footer class="footer"><span>Catatan layanan ${esc(t.name)}.</span><span>Akses akun individual · Top Hills.</span></footer></div>`;}
function newOrder(prefill={}){canEdit();if(!db.settings.packages.length||!db.employees.some(e=>e.active)){openModal('Siapkan laundry terlebih dahulu',`<p>Tambahkan karyawan aktif dan atur paket beserta tarif sebelum mencatat order pertama.</p>${ui.role==='Owner'?btn('Siapkan usaha','readiness','','btn primary'): '<p>Hubungi Owner untuk menyiapkan layanan.</p>'}`);return;}const p=db.settings.packages[0];openModal('Catat laundry baru',`<form data-form="order"><div class="notice blue">${icon('laundry')}Nomor berikut <b>LDR-${String(db.settings.labelNext).padStart(4,'0')}</b>. Satu paket dan target per order.</div><div class="form-grid">${select('Jalur penerimaan','mode',['Antar langsung','Jemput'],prefill.mode||'Antar langsung')}${select('Pelanggan demo','tenantId',[...db.tenants.filter(t=>t.status==='Aktif').map(t=>[t.id,t.name+' · '+t.room]),['public','Customer umum (demo)']],prefill.tenantId||db.tenants.find(t=>t.status==='Aktif')?.id||'public')}${field('Nama customer umum (jika dipilih)','publicName','text','','maxlength="60" placeholder="Nama fiktif"')}${field('Alamat customer umum','address','text','','maxlength="120" placeholder="Alamat demo / titik serah"')}${field('Kontak customer umum','contact','text','WA-DEMO-UMUM','maxlength="40"')}${field('Jumlah kantong','bags','number',prefill.bags||1,'min="1" max="26" required')}${select('Paket · tarif demo per kg','package',db.settings.packages.map((p,i)=>[i,`${p.name} · ${money(p.price)}/kg`]),0)}${field('Berat setelah timbang (kg)','weight','number',prefill.mode==='Jemput'?0:3,'min="0" max="100" step="0.1" required')}${select('Petugas penanggung jawab','pic',db.employees.filter(e=>e.active).map(e=>[e.id,e.name]),ui.employee)}${select('Pengembalian','returnMode',['Ambil di counter','Antar ke kamar'],prefill.returnMode||'Ambil di counter')}${field('Target selesai','due','datetime-local',dueFor(p.hours),'required')}${field('Check-out tamu (wajib untuk penginapan)','checkout','datetime-local',prefill.checkout||'')}${area('Catatan khusus / jadwal jemput','note',prefill.note||'')}</div><div class="calculation" id="price-preview">Estimasi ${money(3*p.price)} · tarif demo, tanpa pembulatan minimum.</div><div class="evidence-box"><h3>Simulasi bukti penerimaan</h3><p>Centang untuk menandai bukti fiktif tersedia. Tidak mengunggah atau mengirim data ke layanan lain.</p>${check('Jejak permintaan/check-in customer resmi','chat',true)}${check('Label terpasang pada semua kantong','label',prefill.mode!=='Jemput')}${check('Foto label + angka timbangan tersedia','weigh',prefill.mode!=='Jemput')}${check('Resi telah diperiksa customer','receipt',prefill.mode!=='Jemput')}${check('Jika target melewati check-out: alternatif disetujui Owner dan customer','checkoutApproval')}</div>${field('ID permintaan portal','requestId','hidden',prefill.requestId||'')}${formFoot('Buat order','Pesanan jemput boleh dibuat tanpa berat. Berat final dan bukti timbang wajib dilengkapi saat diterima.')}</form>`,true);}
function orderDetail(id){const o=db.orders.find(x=>x.id===id);if(!o)throw Error('Order tidak ditemukan.');ui.selected=id;const terminal=['Selesai','Dibatalkan'].includes(o.stage),next=o.stage==='Pesanan Masuk'&&o.mode==='Antar langsung'?'Diterima Laundry':stages[stages.indexOf(o.stage)+1];openModal(`${esc(o.customer)} <span class="muted">/ ${o.id}</span>`,`<div class="order-detail-meta">${badge(o.stage,statusColor(o.stage))}${badge(o.payment,statusColor(o.payment))}${badge(alertFor(o,ui.date).label,alertFor(o,ui.date).level)}</div><div class="detail-grid"><div><span>Kamar / jalur</span><strong>${esc(THServices.location(o)||o.room)} · ${esc(o.roomType||o.type)}</strong><small>${esc(o.contact)} · ${esc(o.mode)}</small></div><div><span>Layanan</span><strong>${esc(THServices.quantityText(o))} · ${esc(o.package)}</strong></div><div><span>Tagihan demo</span><strong>${money(o.total)}</strong></div><div><span>Target selesai</span><strong>${datetime(o.due)}</strong></div><div><span>Check-out / akhir sewa</span><strong>${o.checkout?datetime(o.checkout):dt(getTenant(o.tenantId)?.end)}</strong></div><div><span>Label ${o.bags} kantong</span><strong>${labelFor(o)}</strong></div></div>${o.note?`<div class="notice yellow">${icon('note')}${esc(o.note)}</div>`:''}<form data-form="evidence" data-id="${o.id}"><div class="form-grid">${select('PIC order','pic',db.employees.filter(e=>e.active||e.id===o.pic).map(e=>[e.id,e.name]),o.pic,terminal?'disabled':'')}${field('Rak / lokasi barang','rack','text',o.rack||o.stage,'maxlength="70" '+(terminal?'disabled':''))}${o.stage==='Pesanan Masuk'||o.stage==='Menunggu Dijemput'||o.stage==='Sudah Dijemput'?serviceQuantityFields(THServices.snapshot(o),o):''}${field('Nama penerima','recipient','text',o.recipient,'maxlength="70" '+(terminal?'disabled':''))}${field('Referensi bukti simulasi','evidenceRef','text',o.evidenceRef||'BUKTI-DEMO-'+o.id,'maxlength="160" '+(terminal?'disabled':''))}</div><div class="evidence-box"><h3>Rantai bukti <span class="muted">· simulasi</span></h3><p>Centang sesuai skenario latihan. Bukti ini bukan foto, chat, atau mutasi sungguhan.</p><div class="check-grid">${[['chat','Jejak customer resmi'],['label','Label fisik terpasang'],...(o.mode==='Jemput'?[['pickup','Foto kantong di titik jemput'],['pickupAck','Customer: SUDAH DIJEMPUT']]:[]),['weigh','Bukti timbang / hitung barang sesuai layanan'],['receipt','Resi terkirim dan diperiksa'],['qc','QC sesuai layanan'],['packed','Dikemas dan berlabel'],['readyMessage','Pemberitahuan siap'],['handover','Bukti dan waktu penyerahan'],['customerAck','Customer: DITERIMA'],['thirdParty','Izin tertulis jika penerima pihak lain']].map(([k,l])=>`<label class="check"><input type="checkbox" name="${k}" ${o.evidence[k]?'checked':''} ${terminal?'disabled':''}><span>${l}</span></label>`).join('')}</div></div><div class="form-error" role="alert"></div>${!terminal?'<button type="submit" class="btn">'+icon('check')+'Simpan bukti & penugasan</button>':''}</form><div class="detail-actions">${!terminal&&o.stage!=='Tertahan'?btn(next==='Selesai'?'Konfirmasi selesai':'Lanjut: '+next,'advance',o.id,'btn primary','arrow'):''}${o.stage==='Siap Diserahkan'?btn('Diambil → selesai','complete',o.id,'btn','check'):''}${o.stage==='Tertahan'?btn('Lepas status tertahan','resume',o.id,'btn primary','arrow'):''}${!paid(o)&&o.stage!=='Dibatalkan'?btn('Catat pembayaran','payment',o.id,'btn','wallet'):''}${!terminal?btn('Tahan / batalkan','hold',o.id,'btn ghost','alert'):''}${btn('Resi','receipt',o.id,'btn ghost','note')}${ui.role==='Owner'?btn('Koreksi','correction',o.id,'btn ghost','edit'):''}</div>${o.settlementId?`<div class="notice">${icon('shield')}Settlement ${esc(o.settlementId)} · ${esc(db.settlements.find(s=>s.id===o.settlementId)?.status)}</div>`:''}<details class="history" ${terminal?'open':''}><summary>Riwayat order · ${o.history.length} catatan</summary>${o.history.map(h=>`<div><span>${datetime(h.at)} · ${esc(h.actor)}</span><p>${esc(h.text)}</p></div>`).join('')}${o.completed?`<p>Durasi historis ${((new Date(o.completed)-new Date(o.created))/36e5).toFixed(1)} jam. Umur aktif ditutup menjadi 0.</p>`:''}</details>`,true);ui.selected=id;}
function paymentForm(id){canEdit();const o=db.orders.find(o=>o.id===id);openModal('Catat pembayaran',`<form data-form="payment" data-id="${id}"><div class="receipt-total"><span>${o.id} · ${esc(o.customer)}</span><strong>${money(o.total)}</strong></div><div class="notice">${icon('shield')}Pencatatan demo saja. Tidak ada QRIS atau rekening yang dapat dibayar.</div><div class="form-grid">${select('Metode','method',['QRIS','Transfer','Cash'],o.method)}${field('Nominal bukti / penerimaan','amount','number',o.total,'min="0" step="0.01" required')}${field('Referensi bukti fiktif','reference','text',o.paymentRef||'BUKTI-DEMO-'+o.id,'maxlength="80" required')}${select('Lokasi penerimaan cash','location',['Counter','Kamar saat pengembalian'])}</div><div class="evidence-box">${check('Mutasi masuk resmi telah cocok (simulasi, Owner saja)','verified')}${check('Cash: dihitung bersama customer, kuitansi dua rangkap disiapkan','cashReceipt')}${check('Cash di kamar: konfirmasi nominal customer + pouch segel tersedia','roomCash')}</div><p class="form-note">Noncash oleh Operator selalu Menunggu Verifikasi. Cash mendapat nomor kuitansi otomatis dan tetap Lunas Cash meskipun belum disetor.</p>${formFoot('Simpan pembayaran')}</form>`);}
function tenantForm(id){canEdit();const t=db.tenants.find(t=>t.id===id)||{type:'Kost putri',start:ui.date,end:dayShift(ui.date,365),rent:15000000,status:'Aktif'};openModal(id?'Kelola penghuni':'Tambah penghuni demo',`<form data-form="tenant" data-id="${id||''}"><div class="form-grid">${field('Nama fiktif','name','text',t.name,'required maxlength="60"')}${field('Kontak demo','contact','text',t.contact||'WA-DEMO-','required maxlength="40"')}${select('Jenis hunian','type',['Kost putri','Penginapan'],t.type)}${select('Gedung','building',['A','B','C'],t.building)}${field('Kode kamar','room','text',t.room,'required maxlength="20"')}${select('Status penghuni','status',['Aktif','Check-out','Arsip'],t.status)}${field('Mulai tinggal','start','date',t.start,'required')}${field('Akhir tinggal','end','date',t.end,'required')}${field('Nilai sewa periode (demo)','rent','number',t.rent,'min="0" max="1000000000" required')}${area('Catatan','note',t.note)}</div>${formFoot('Simpan penghuni','Menyimpan nilai sewa tidak otomatis membuat tagihan. Buat periode dan nominal tagihan di menu Collection.')}</form>`);}
function invoiceDetail(id){const i=db.invoices.find(i=>i.id===id);openModal('Rincian tagihan',`<div class="receipt-total"><span>${id} · ${esc(getTenant(i.tenantId)?.name)}</span><strong>${money(i.amount-i.paid)}</strong><small>sisa dari total ${money(i.amount)}</small></div><p>${esc(i.title)} · jatuh tempo ${dt(i.due)}</p><div class="button-row">${i.amount>i.paid?btn('Catat penerimaan','invoice-pay',id,'btn primary','wallet'):badge('Lunas','green')}${btn('Salin pengingat','invoice-reminder',id,'btn','copy')}</div><h3>Riwayat penerimaan</h3>${i.history.map(h=>`<div class="audit-entry"><strong>${money(h.amount)} · ${esc(h.method)}</strong><p>${datetime(h.at)} · ${esc(h.reference)} · ${esc(h.actor)}</p></div>`).join('')||'<p class="muted">Saldo awal demo: '+money(i.paid)+'. Belum ada penerimaan tambahan.</p>'}`);}
function invoiceForm(){canEdit();openModal('Buat tagihan hunian',`<form data-form="invoice"><div class="form-grid">${select('Penghuni','tenantId',db.tenants.map(t=>[t.id,t.name+' · '+t.room]))}${field('Periode / keterangan','title','text','Sewa periode demo','required maxlength="100"')}${field('Nominal tagihan','amount','number',1500000,'min="1" max="1000000000" required')}${field('Tanggal invoice','issuedDate','date',ui.date,'required')}${field('Tanggal jasa diperoleh','serviceDate','date','','')}${field('Jatuh tempo','due','date',ui.date,'required')}${ui.role==='Owner'?check('Tanggal pengakuan jasa telah disetujui','recognitionApproved'):''}</div>${formFoot('Buat tagihan','Aturan sewa dan nominal tagihan merupakan contoh, belum ditetapkan oleh SOP laundry.')}</form>`);}
function reportForm(id){canEdit();if(!db.employees.some(e=>e.active&&(ui.role==='Owner'||e.id===ui.employee)))throw Error('Tambahkan dan tautkan karyawan aktif sebelum membuat laporan.');const r=db.reports.find(r=>r.id===id)||{employeeId:ui.employee,date:ui.date,division:'Laundry',hours:1};if(id&&ui.role==='Operator'&&r.employeeId!==ui.employee)throw Error('Laporan bukan milik petugas ini.');openModal(id?'Perbarui laporan':'Laporan aktivitas harian',`<form data-form="report" data-id="${id||''}"><div class="form-grid">${select('Karyawan','employeeId',db.employees.filter(e=>e.active||e.id===r.employeeId).filter(e=>ui.role==='Owner'||e.id===ui.employee).map(e=>[e.id,e.name]),r.employeeId)}${field('Tanggal aktivitas','date','date',r.date,'required')}${select('Alokasi pekerjaan','division',['Laundry','Global'],r.division)}${field('Durasi (jam)','hours','number',r.hours,'min="0.1" max="24" step="0.1" required')}${area('Aktivitas yang dikerjakan','activity',r.activity,'required maxlength="600"')}${area('Hasil / output terukur','output',r.output,'required maxlength="600"')}${select('Order terkait (opsional)','orderId',[['','Tidak terkait order'],...db.orders.map(o=>[o.id,o.id+' · '+o.customer])],r.orderId)}${field('Referensi bukti demo (opsional)','evidence','text',r.evidence,'maxlength="120"')}${area('Hambatan / dukungan yang dibutuhkan','obstacle',r.obstacle,'maxlength="500"')}${area('Rencana berikutnya','next',r.next,'required maxlength="500"')}</div>${formFoot('Kirim laporan ke Owner','Laporan tersimpan di ruang kerja dan dapat ditinjau Owner.')}</form>`,true);}
function reportDetail(id){const r=db.reports.find(r=>r.id===id);if(ui.role==='Operator'&&r.employeeId!==ui.employee)throw Error('Laporan bukan milik petugas ini.');openModal('Catatan '+esc(getEmp(r.employeeId)),`<div class="order-detail-meta">${badge(r.division,'blue')}${badge(r.status,'neutral')}<span>${dt(r.date)} · ${r.hours} jam</span></div><h3>${esc(r.activity)}</h3><dl class="report-detail"><dt>Hasil</dt><dd>${esc(r.output)}</dd><dt>Hambatan</dt><dd>${esc(r.obstacle||'Tidak ada yang dicatat.')}</dd><dt>Langkah berikut</dt><dd>${esc(r.next)}</dd><dt>Order / bukti</dt><dd>${esc(r.orderId||'—')} / ${esc(r.evidence||'—')}</dd><dt>Feedback Owner</dt><dd>${esc(r.feedback||'Belum ditinjau.')}</dd></dl>${ui.role==='Owner'?`<form data-form="review-report" data-id="${id}">${area('Feedback Owner','feedback',r.feedback,'required maxlength="600"')}${select('Hasil tinjauan','status',['Ditinjau','Perlu perbaikan'],r.status)}${formFoot('Simpan tinjauan')}</form>`:btn('Perbarui laporan','edit-report',id,'btn','edit')}`);}
function employeeForm(id){ownerOnly();const e=db.employees.find(e=>e.id===id)||{division:'Laundry',color:'blue'};openModal(id?'Edit profil karyawan':'Tambah karyawan',`<form data-form="employee" data-id="${id||''}"><div class="form-grid">${field('Nama fiktif','name','text',e.name,'required maxlength="60"')}${field('Jabatan','position','text',e.position,'required maxlength="60"')}${select('Alokasi bisnis','division',['Laundry','Global','Global & Laundry'],e.division)}${select('Warna penanda','color',[['blue','Biru'],['green','Hijau'],['yellow','Kuning']],e.color)}</div>${formFoot('Simpan karyawan')}</form>`);}
function evaluationForm(id){ownerOnly();const v=db.evaluations.find(v=>v.id===id)||{employeeId:ui.employee,date:ui.date,scores:[3,3,3,3,3,3]};openModal('Penilaian Owner',`<form data-form="evaluation" data-id="${id||''}"><div class="form-grid">${select('Karyawan','employeeId',db.employees.map(e=>[e.id,e.name]),v.employeeId)}${field('Tanggal yang dinilai','date','date',v.date,'required')}</div><div class="evaluation-inputs">${scoreKeys.map((k,i)=>`<label><span>${k}</span><input type="range" name="score${i}" min="1" max="5" step="1" value="${v.scores[i]}" aria-label="Nilai ${k}"><output>${v.scores[i]} / 5</output></label>`).join('')}</div><p class="form-note">1 perlu pendampingan · 2 belum konsisten · 3 sesuai harapan · 4 konsisten baik · 5 melampaui harapan. Lingkungan kerja menilai dukungan dan kondisi kerja.</p>${area('Bukti aktivitas yang mendasari skor','evidence',v.evidence,'required maxlength="700"')}${area('Feedback yang spesifik','feedback',v.feedback,'required maxlength="700"')}${area('Rencana perbaikan / dukungan dari Owner','next',v.next,'required maxlength="700"')}${formFoot('Simpan penilaian','Satu penilaian per karyawan per tanggal. Pembaruan dicatat dalam jejak aktivitas.')}</form>`,true);}
function settlementForm(){canEdit();const os=db.orders.filter(o=>o.payment==='Lunas Cash'&&!o.settlementId);if(!os.length){toast('Tidak ada penerimaan cash yang belum closing.');return;}const total=os.reduce((n,o)=>n+o.total,0);openModal('Closing cash harian',`<form data-form="settlement"><div class="notice blue">${icon('wallet')}${os.length} kuitansi · wajib setor <b>${money(total)}</b>. Float dipisahkan.</div><div class="form-grid">${field('Tanggal closing','date','date',ui.date,'required')}${select('Shift','shift',['PAGI','SORE','HARIAN'],'HARIAN')}${field('Float awal yang disetujui','float','number',db.settings.float,'min="0" max="100000000" required')}${field('Uang fisik termasuk float','physical','number',total+db.settings.float,'min="0" max="100000000" required')}${field('Hitung ulang bersama saksi','recount','number',total+db.settings.float,'min="0" max="100000000" required')}${select('Saksi closing','witness',db.employees.filter(e=>e.active&&!(ui.role==='Operator'&&e.id===ui.employee)).map(e=>[e.id,e.name]))}${field('Nomor amplop','envelope','text','ENV-DEMO-'+ui.date.replaceAll('-',''),'required maxlength="70"')}${field('Nomor segel','seal','text','SEAL-DEMO-'+ui.date.replaceAll('-',''),'required maxlength="70"')}${field('Pemegang kunci cash box','keyHolder','text','Owner Demo','required maxlength="60"')}${select('Petugas yang menyetor','depositor',db.employees.filter(e=>e.active).map(e=>[e.id,e.name]))}${area('Selisih / kondisi / tindak lanjut','note','','maxlength="600"')}</div><div class="calculation" id="settlement-preview">Selisih: ${money(0)} · wajib setor ${money(total)}</div><div class="evidence-box">${check('Kuitansi dicocokkan, hitung ulang disaksikan, amplop ditandatangani dan disimpan di cash box','confirmed')}</div><p class="form-note">Kuitansi: ${os.map(o=>esc(o.receipt)).join(', ')}. Cash setelah closing masuk batch berikutnya.</p>${formFoot('Simpan closing','Jika ada selisih, jelaskan penyebab dan tindakan. Jangan mengubah transaksi pelanggan agar kas tampak cocok.')}</form>`,true);}
function settlementDetail(id){const s=db.settlements.find(s=>s.id===id);openModal('Settlement '+esc(id),`${badge(s.status,statusColor(s.status))}<dl class="summary-list"><div><dt>Float</dt><dd>${money(s.float)}</dd></div><div><dt>Wajib setor (kuitansi)</dt><dd>${money(s.expectedDeposit)}</dd></div><div><dt>Fisik setelah float</dt><dd>${money(s.deposit)}</dd></div><div><dt>Selisih</dt><dd class="${s.difference?'text-red':''}">${money(s.difference)}</dd></div><div><dt>Amplop / segel</dt><dd>${esc(s.envelope)} / ${esc(s.seal)}</dd></div><div><dt>Saksi / petugas setor</dt><dd>${esc(s.witness)} / ${esc(s.depositor)}</dd></div><div><dt>Cash box / kunci</dt><dd>${esc(s.keyHolder)} · ${datetime(s.createdAt)}</dd></div></dl><p class="muted">Order: ${s.orderIds.join(', ')}</p><p>${esc(s.note||'Tidak ada catatan tambahan.')}</p>${s.status==='Belum Disetor'?`<form data-form="deposit" data-id="${id}"><h3>Catat setoran simulasi</h3>${field('Nominal disetor','amount','number',s.deposit,'min="0" required')}${field('Referensi bukti setor','reference','text','SETOR-DEMO-'+id,'required maxlength="120"')}${field('Waktu setoran','at','datetime-local',ui.date+'T16:00','required')}${formFoot('Catat sudah disetor')}</form>`:s.status==='Sudah Disetor'?`${ui.role==='Owner'?`<form data-form="verify-settlement" data-id="${id}"><h3>Cocokkan mutasi oleh Owner</h3>${field('Nominal masuk di mutasi','amount','number',s.deposit,'min="0" required')}${field('Referensi mutasi resmi (demo)','reference','text','MUTASI-DEMO-'+id,'required maxlength="120"')}${formFoot('Verifikasi setoran')}</form>`:'<div class="notice blue">Menunggu Owner mencocokkan mutasi. Operator tidak dapat memverifikasi.</div>'}`:`<div class="notice green">${icon('check')}Mutasi ${esc(s.bankReference)} · ${datetime(s.verifiedAt)}</div>`}${s.difference?`<div class="notice yellow">Selisih ${money(s.difference)} tetap tercatat.${s.resolved?' Tindak lanjut: '+esc(s.resolution):' Tetapkan tindak lanjut Owner.'}</div>${ui.role==='Owner'&&!s.resolved?`<form data-form="resolve-difference" data-id="${id}">${area('Penyebab, penyelesaian, dan referensi bukti','resolution','','required maxlength="600"')}${formFoot('Tutup selisih dengan bukti')}</form>`:''}`:''}`);}
function settingsForm(){ownerOnly();const s=db.settings;openModal('Pengaturan ruang kerja',`<form data-form="settings"><div class="notice blue">${icon('settings')}Lengkapi parameter usaha sebelum order pertama. Jam pada formulir mengikuti WIB.</div><div class="form-grid">${field('Tanggal acuan laporan','date','date',s.date,'required')}${field('Jam buka','hoursOpen','time',s.hoursOpen,'required')}${field('Jam tutup','hoursClose','time',s.hoursClose,'required')}${field('Batas respons WA (menit)','responseMinutes','number',s.responseMinutes,'min="1" max="120" required')}${field('Closing setelah tutup (menit)','closingMinutes','number',s.closingMinutes,'min="1" max="180" required')}${field('Float kembalian','float','number',s.float,'min="0" max="100000000" required')}${field('Batas cash di lokasi','maxCash','number',s.maxCash,'min="1" max="100000000" required')}${field('Tenggat setor hari kerja berikut','depositTime','time',s.depositTime,'required')}${field('Label berikut','labelNext','number',s.labelNext,'min="'+s.labelNext+'" required')}${field('Batas rentang label','labelEnd','number',s.labelEnd,'min="'+s.labelNext+'" required')}${field('Kuitansi berikut','receiptNext','number',s.receiptNext,'min="'+s.receiptNext+'" required')}${field('Batas rentang kuitansi','receiptEnd','number',s.receiptEnd,'min="'+s.receiptNext+'" required')}</div><h3>Paket dan harga layanan</h3><p class="muted">Berlaku untuk order baru. Order lama mempertahankan tarifnya.</p>${(s.packages.length?s.packages:[{name:'',price:'',hours:48}]).map((p,i)=>serviceSetting(p,i)).join('')}<div id="package-add-target"></div>${btn('Tambah paket','package-add','','btn small','plus')}${formFoot('Simpan pengaturan')}</form><div class="settings-data"><h3>Cadangan data fiktif</h3><p>${window.THCloud?'Data operasional, transaksi dan bukti tersimpan di ruang kerja bersama. Gunakan Laporan untuk koreksi dan migrasi data.':'Data demo disimpan di browser ini.'}</p><div class="button-row">${btn('Unduh cadangan JSON','backup','','btn','download')}${window.THCloud?'':btn('Pulihkan cadangan','restore','','btn','note')+btn('Reset data demo','reset','','text-btn danger')}</div><input id="restore-file" type="file" accept=".json,application/json" hidden></div>`,true);}
function openReceipt(o,consumer=false){openModal('Resi laundry',`<pre class="receipt-paper">${esc(templateText(3,o))}</pre><div class="button-row">${btn('Salin resi','copy-receipt',o.id,'btn','copy')}${btn('Unduh .txt','download-receipt',o.id,'btn','download')}${consumer&&o.evidence.handover&&!o.evidence.customerAck&&o.stage!=='Selesai'?btn('Konfirmasi DITERIMA','consumer-confirm',o.id,'btn primary','check'):''}</div>${consumer?'<p class="form-note">Tombol konfirmasi muncul setelah petugas mencatat bukti penyerahan.</p>':''}`);}
function openTemplate(index){const oid=ui.templateOrder||db.orders[0]?.id;if(!oid)throw Error('Buat satu order demo dahulu.');const o=db.orders.find(o=>o.id===oid)||db.orders[0];openModal(templateNames[index],`<label class="field"><span>Isi dengan data order</span><select id="template-order" data-template="${index}">${db.orders.map(x=>`<option value="${x.id}" ${x.id===o.id?'selected':''}>${x.id} · ${esc(x.customer)}</option>`).join('')}</select></label><textarea class="template-text" id="template-text" rows="13">${esc(templateText(index,o))}</textarea><div class="button-row">${btn('Salin teks','copy-template','','btn primary','copy')}${btn('Unduh .txt','download-template',String(index),'btn','download')}</div><p class="form-note">Tinjau placeholder [seperti ini] sebelum dipakai. Semua data contoh fiktif; tidak dikirim otomatis.</p>`);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n')}
function confirmation(title,body,form,id='',label='Konfirmasi'){openModal(title,`<form data-form="${form}" data-id="${esc(id)}"><p>${body}</p>${formFoot(label)}</form>`);}
const actions={
nav(id){ui.page=id;ui.search='';ui.filter='Semua';ui.tab=id==='finance'?'summary':id==='operations'?'laundry':id==='guide'?'rules':id==='team'?(ui.role==='Owner'?'members':'reports'):'laundry';render();window.scrollTo({top:0,behavior:'smooth'});},
tab(id){ui.tab=id;ui.search='';ui.filter='Semua';render();},goto(id){if(['laundry','invoices','tenants','closing'].includes(id)){ui.page='operations';ui.tab=id}else{ui.page='team';ui.tab=id}ui.search='';render();},
date(id){ui.date=id;render();},'pick-date'(){openModal('Pilih hari jurnal',`<form data-form="pick-date">${field('Tanggal jurnal','date','date',ui.date,'required')}${formFoot('Buka jurnal')}</form>`);},view(id){ui.view=id;render();},close:closeModal,
'new-order'(){newOrder()},order:orderDetail,'new-tenant'(){tenantForm()},tenant:tenantForm,'new-invoice':invoiceForm,invoice:invoiceDetail,'new-report'(){reportForm()},'edit-report':reportForm,report:reportDetail,'new-employee'(){employeeForm()},employee:employeeForm,'new-evaluation'(){evaluationForm()},evaluation:evaluationForm,'new-settlement':settlementForm,settlement:settlementDetail,settings:settingsForm,payment:paymentForm,
async advance(id){canEdit();const o=db.orders.find(o=>o.id===id),next=o.stage==='Pesanan Masuk'&&o.mode==='Antar langsung'?'Diterima Laundry':stages[stages.indexOf(o.stage)+1];if(next==='Siap Diserahkan'&&(!o.rack||!o.evidence.readyMessage))throw Error('Simpan lokasi rak dan pemberitahuan siap sebelum melanjutkan.');TH.advance(o,next,actor(),ui.date);audit(`${id}: ${next}`);await persist('Status order diperbarui.');orderDetail(id)},
async complete(id){canEdit();const o=db.orders.find(o=>o.id===id);TH.advance(o,'Selesai',actor(),ui.date);audit(`${id}: selesai dengan konfirmasi customer`);await persist('Order selesai. Riwayat durasi tersimpan.');orderDetail(id)},
hold(id){canEdit();openModal('Tahan atau batalkan order',`<form data-form="hold" data-id="${id}">${select('Tindakan','action',['Tertahan',...(ui.role==='Owner'?['Dibatalkan']:[])])}${area('Alasan, PIC, dan tindak lanjut','reason','','required maxlength="500"')}${formFoot('Simpan status','Order tidak dihapus. Pembatalan dibatasi kepada Owner; penerimaan yang sudah lunas perlu penyelesaian refund terpisah.')}</form>`)},
resume(id){canEdit();const o=db.orders.find(o=>o.id===id);if(o.stage!=='Tertahan')throw Error('Order tidak tertahan.');openModal('Lanjutkan order tertahan',`<form data-form="resume" data-id="${id}">${area('Penyelesaian masalah dan referensi bukti','reason','','required maxlength="400"')}${formFoot('Lanjutkan dari tahap sebelumnya')}</form>`)},
receipt(id){openReceipt(db.orders.find(o=>o.id===id))},'copy-receipt'(id){copyText(templateText(3,db.orders.find(o=>o.id===id)))},'download-receipt'(id){download('Resi-demo-'+id+'.txt',templateText(3,db.orders.find(o=>o.id===id)))},
correction(id){ownerOnly();const o=db.orders.find(o=>o.id===id);openModal('Catatan koreksi Owner',`<form data-form="correction" data-id="${id}"><div class="notice">${icon('shield')}Nilai lama tetap ada di audit. Pembayaran yang sudah tercatat membatasi koreksi total.</div>${serviceQuantityFields(THServices.snapshot(o),o)}${field('Total tagihan terkoreksi','total','number',o.total,'min="0" max="100000000" step="0.01" required')}${area('Alasan dan referensi bukti / persetujuan','reason','','required maxlength="600"')}${formFoot('Simpan koreksi')}</form>`)},
'invoice-pay'(id){canEdit();const i=db.invoices.find(i=>i.id===id);openModal('Catat penerimaan hunian',`<form data-form="invoice-pay" data-id="${id}"><div class="notice blue">Sisa tagihan ${money(i.amount-i.paid)}. Pencatatan simulasi, tidak memproses pembayaran.</div>${field('Nominal diterima','amount','number',i.amount-i.paid,'min="1" max="'+(i.amount-i.paid)+'" required')}${select('Metode penerimaan','method',['Transfer demo','Cash demo'])}${field('Referensi penerimaan fiktif','reference','text','TERIMA-DEMO-'+id,'required maxlength="120"')}${formFoot('Catat penerimaan')}</form>`)},
'invoice-reminder'(id){const i=db.invoices.find(i=>i.id===id),t=getTenant(i.tenantId);copyText(`TAGIHAN TOP HILLS · DEMO\nHalo ${t.name}, berikut tagihan ${i.title}.\nKamar: ${t.room}\nTotal: ${money(i.amount)}\nDiterima: ${money(i.paid)}\nSisa: ${money(i.amount-i.paid)}\nJatuh tempo: ${dt(i.due)}\nIni contoh pesan; tidak memuat rekening atau pembayaran aktif.`)},
'employee-toggle'(id){ownerOnly();const e=db.employees.find(e=>e.id===id);confirmation(e.active?'Nonaktifkan karyawan?':'Aktifkan karyawan?',`${esc(e.name)} ${e.active?'akan dikeluarkan dari daftar petugas aktif. Alihkan semua order terbuka terlebih dahulu. Laporan dan penilaian tetap tersedia.':'akan kembali tersedia untuk penugasan.'}`,'employee-toggle',id,e.active?'Nonaktifkan':'Aktifkan')},
alerts(){const os=db.orders.filter(o=>alertFor(o,ui.date).level!=='green'),waiting=db.orders.filter(o=>o.payment==='Menunggu Verifikasi');openModal('Perlu perhatian',`<h3>Prioritas laundry</h3>${os.map(orderRow).join('')||'<p>Antrean dalam target.</p>'}<h3>Menunggu verifikasi pembayaran</h3>${waiting.map(orderRow).join('')||'<p>Tidak ada pembayaran menunggu.</p>'}<h3>Laporan perlu tinjauan</h3><p>${db.reports.filter(r=>r.status==='Dikirim').length} laporan masuk.</p><h3>Setoran perlu diperiksa</h3><p>${db.settlements.filter(s=>s.status==='Sudah Disetor').length} setoran menunggu Owner.</p>`)},
'copy-closing'(){copyText(closingText())},template(id){openTemplate(Number(id))},'copy-template'(){copyText(document.querySelector('#template-text').value)},'download-template'(id){download('Template-'+templateNames[Number(id)].replaceAll(' ','-')+'.txt',document.querySelector('#template-text').value)},
'source-sop'(){openModal('SOP sumber · v0.2',`<p class="muted">Teks dari dokumen yang dilampirkan. Tabel disajikan sebagai teks berurutan. Aplikasi demo memakai profil petugas fiktif.</p><pre class="sop-source">${esc(window.SOP_SOURCE||'Sumber tidak tersedia.')}</pre>`,true)},
backup(){canEdit();download('Top-Hills-Cadangan-'+ui.date+'.json',JSON.stringify(db,null,2),'application/json');toast('Cadangan JSON diunduh.')},restore(){ownerOnly();document.querySelector('#restore-file').click()},reset(){ownerOnly();confirmation('Reset data demo?',`Seluruh perubahan dalam browser ini akan diganti dengan data awal. Unduh cadangan terlebih dahulu jika ingin menyimpannya.`,'reset','','Reset data demo')},
'export-orders'(){canEdit();download('Top-Hills-Laundry.csv',csv([['Order','Pelanggan','Kontak','Jenis pelanggan','Gedung','Lantai','Kamar','Jenis kamar','Checkout','Berat fisik kg','Jumlah tagihan','Satuan','Layanan','Tarif','Tagihan','Status barang','Status pembayaran','PIC','Masuk','Target'],...db.orders.map(o=>[o.id,o.customer,o.contact,o.type,o.building||'',o.floor||'',o.room,o.roomType||'',o.checkout||'',o.weight,o.billedQuantity??o.weight,THServices.snapshot(o).unit,o.package,o.rate,o.total,o.stage,o.payment,getEmp(o.pic),o.created,o.due])]),'text/csv')},
'export-invoices'(){canEdit();download('Top-Hills-Tagihan.csv',csv([['ID','Penghuni','Keterangan','Tagihan','Diterima','Sisa','Jatuh tempo'],...db.invoices.map(i=>[i.id,getTenant(i.tenantId)?.name,i.title,i.amount,i.paid,i.amount-i.paid,i.due])]),'text/csv')},
'export-reports'(){canEdit();download('Top-Hills-Laporan.csv',csv([['Karyawan','Tanggal','Alokasi','Aktivitas','Hasil','Jam','Hambatan','Rencana','Status','Feedback'],...db.reports.filter(r=>ui.role==='Owner'||r.employeeId===ui.employee).map(r=>[getEmp(r.employeeId),r.date,r.division,r.activity,r.output,r.hours,r.obstacle,r.next,r.status,r.feedback])]),'text/csv')},
'export-audit'(){ownerOnly();download('Top-Hills-Audit.csv',csv([['Waktu','Pengubah','Perubahan'],...db.audit.map(a=>[a.at,a.actor,a.text])]),'text/csv')},
'consumer-request'(){if(ui.role!=='Konsumen')return;openModal('Minta jemput laundry',`<form data-form="consumer-request"><p>Untuk ${esc(getTenant(ui.consumer).name)} · ${esc(getTenant(ui.consumer).room)}</p>${field('Jumlah kantong','bags','number',1,'min="1" max="26" required')}${field('Waktu tersedia','time','datetime-local',ui.date+'T14:00','required')}${select('Pengembalian','returnMode',['Antar ke kamar','Ambil di counter'])}${area('Catatan barang khusus','note','','maxlength="500"')}${formFoot('Simpan permintaan','Permintaan masuk ke antrean Operator di perangkat yang sama. Berat dan harga ditentukan setelah ditimbang.')}</form>`)},
'consumer-order'(id){const o=db.orders.find(o=>o.id===id&&o.tenantId===ui.consumer);if(!o)throw Error('Order tidak tersedia.');openReceipt(o,true)},
'consumer-confirm'(id){const o=db.orders.find(o=>o.id===id&&o.tenantId===ui.consumer);if(!o||!o.evidence.handover||!o.recipient)throw Error('Penyerahan belum dicatat petugas.');o.evidence.customerAck=true;TH.advance(o,'Selesai',getTenant(ui.consumer).name,ui.date);audit(`${id}: customer demo mengonfirmasi DITERIMA`);closeModal();persist('Terima kasih. Penerimaan laundry tercatat.')},
requests(){canEdit();openModal('Permintaan dari portal customer',db.requests.length?db.requests.map(r=>`<section class="request-card"><h3>${esc(getTenant(r.tenantId)?.name)} · ${r.bags} kantong</h3><p>${datetime(r.time)} · ${esc(r.returnMode)}</p><p>${esc(r.note)}</p>${badge(r.status,'blue')}<div class="button-row">${r.status==='Baru'?btn('Proses jadi order','request-process',r.id,'btn primary','plus')+btn('Tolak dengan alasan','request-reject',r.id,'text-btn'):''}</div></section>`).join(''):empty('Belum ada permintaan'))},
'request-process'(id){canEdit();const r=db.requests.find(r=>r.id===id);newOrder({...r,mode:'Jemput',requestId:id,note:'Jadwal jemput: '+datetime(r.time)+'. '+r.note})},
'request-reject'(id){canEdit();openModal('Catat penolakan permintaan',`<form data-form="request-reject" data-id="${id}">${area('Alasan penolakan','reason','','required maxlength="400"')}${formFoot('Simpan alasan')}</form>`)}
};
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;e.preventDefault();const snapshot=JSON.stringify(db);try{const a=actions[target.dataset.action];if(a){if(window.THCloud?.busy)throw Error('Masih menyimpan. Tunggu sampai selesai.');await a(target.dataset.id);}}catch(err){db=JSON.parse(window.THCloud?.state?JSON.stringify(THCloud.state.operations):snapshot);toast(err.message||'Tindakan belum dapat diselesaikan.');}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='role'){ui.role=t.value;ui.page='home';ui.tab='laundry';ui.search='';closeModal();render();}else if(t.id==='employee-select'){ui.employee=t.value;render()}else if(t.id==='order-filter'){ui.filter=t.value;render()}else if(t.dataset.dailyCheck!==undefined){db.settings.checklist[ui.date+'-'+t.dataset.dailyCheck]=t.checked;try{await persist()}catch(err){toast(err.message)}}else if(t.id==='template-order'){ui.templateOrder=t.value;openTemplate(Number(t.dataset.template))}else if(t.id==='restore-file'){restoreFile(t.files[0])}else if(t.closest('[data-form="order"]'))updateOrderEstimate(t.name);});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){ui.search=t.value;const orders=db.orders.filter(o=>(!window.THDateFilters||THDateFilters.matches(o,'laundry'))&&(ui.filter==='Semua'||ui.filter==='Prioritas'&&alertFor(o,ui.date).level!=='green'||ui.filter==='Belum lunas'&&!paid(o)||o.stage===ui.filter)&&`${o.id} ${o.customer} ${o.room} ${o.building||''} ${o.floor||''} ${o.roomType||''}`.toLowerCase().includes(ui.search.toLowerCase()));document.querySelector('#order-results').innerHTML=laundryResults(orders)}else if(t.id==='report-search'){ui.search=t.value;const pos=t.selectionStart;render();const input=document.querySelector('#report-search');input.focus();input.setSelectionRange(pos,pos)}else if(t.type==='range'){t.nextElementSibling.textContent=t.value+' / 5'}else if(t.closest('[data-form="order"]'))updateOrderEstimate(t.name);else if(t.closest('[data-form="settlement"]')){const f=t.form,fd=new FormData(f),total=db.orders.filter(o=>o.payment==='Lunas Cash'&&!o.settlementId).reduce((n,o)=>n+o.total,0);document.querySelector('#settlement-preview').textContent='Selisih: '+money(Number(fd.get('physical'))-Number(fd.get('float'))-total)+' · wajib setor '+money(total)}});
function updateOrderEstimate(changedName){const f=dialog.querySelector('[data-form="order"]');if(!f)return;const fd=new FormData(f),p=db.settings.packages[Number(fd.get('package'))],t=getTenant(fd.get('tenantId'));document.querySelector('#price-preview').textContent='Estimasi '+money(Number(fd.get('weight'))*p.price)+' · '+money(p.price)+'/kg. Target paket '+p.hours+' jam.';const checkout=f.elements.checkout;if(changedName==='tenantId')checkout.value=t?.type==='Penginapan'?t.end+'T12:00':'';if(changedName==='package')f.elements.due.value=dueFor(p.hours);if(changedName==='mode'&&fd.get('mode')==='Jemput'){f.elements.weight.value=0;['label','weigh','receipt'].forEach(k=>f.elements[k].checked=false);document.querySelector('#price-preview').textContent='Berat dan tagihan final ditetapkan setelah laundry tiba dan ditimbang.';}}
async function restoreFile(file){if(!file)return;try{ownerOnly();if(file.size>15000000)throw Error('Cadangan maksimal 15 MB.');const parsed=JSON.parse(await file.text());if(!TH.validateBackup(parsed))throw Error('Format cadangan tidak valid. Data saat ini tidak berubah.');window.pendingRestore=parsed;confirmation('Pulihkan cadangan?',`Cadangan berisi ${parsed.orders.length} order, ${parsed.tenants.length} penghuni, dan ${parsed.reports.length} laporan. Data saat ini akan diganti. Unduh cadangan data saat ini terlebih dahulu bila diperlukan.`,'restore','','Pulihkan cadangan')}catch(e){toast(e.message)}}
function requireText(s,label){if(!String(s||'').trim())throw Error(label+' wajib diisi.');return String(s).trim()}
function finite(v,label,min=0,max=1e9){const n=Number(v);if(!Number.isFinite(n)||n<min||n>max)throw Error(label+' tidak valid.');return n}
function history(o,text){o.history.push({at:new Date().toISOString(),actor:actor(),text});audit(o.id+': '+text)}
const submissions={
'pick-date'(v){ui.date=v.date;closeModal();render();return false},
order(v,f){canEdit();if(db.settings.labelNext>db.settings.labelEnd)throw Error('Rentang label habis. Owner perlu mengalokasikan rentang baru.');const tenant=getTenant(v.tenantId),isPublic=v.tenantId==='public';if(!isPublic&&!tenant)throw Error('Pilih customer.');if(!db.employees.some(e=>e.id===v.pic&&e.active))throw Error('Pilih petugas aktif.');const p=db.settings.packages[Number(v.package)],weight=finite(v.weight,'Berat',0,100),bags=finite(v.bags,'Jumlah kantong',1,26);if(!Number.isInteger(bags))throw Error('Jumlah kantong harus bulat.');const customer=isPublic?requireText(v.publicName,'Nama customer umum'):tenant.name,room=isPublic?requireText(v.address,'Alamat'):tenant.room,contact=isPublic?requireText(v.contact,'Kontak'):tenant.contact;const checkout=tenant?.type==='Penginapan'?requireText(v.checkout,'Tanggal dan jam check-out'):v.checkout;if(!v.chat)throw Error('Jejak permintaan customer wajib tersedia.');const created=new Date().toISOString();if(!Number.isFinite(THJournalCore.timestamp(v.due))||THJournalCore.timestamp(v.due)<Date.parse(created))throw Error('Target selesai tidak boleh sebelum penerimaan.');if(checkout&&THJournalCore.timestamp(v.due)>THJournalCore.timestamp(checkout)&&!v.checkoutApproval)throw Error('Target melewati check-out. Ubah layanan/target atau catat persetujuan alternatif.');let stage='Pesanan Masuk';if(v.mode==='Antar langsung'){if(weight<=0||!v.label||!v.weigh||!v.receipt)throw Error('Antar langsung memerlukan berat final, label, bukti timbang, dan resi.');stage='Diterima Laundry';}const o={id:'LDR-'+String(db.settings.labelNext).padStart(4,'0'),tenantId:tenant?.id||'',customer,contact,type:tenant?.type||'Umum',room,mode:v.mode,bags,weight,package:p.name,rate:p.price,total:Math.round(weight*p.price),stage,payment:'Belum Bayar',method:'QRIS',pic:v.pic,created,due:v.due+'+07:00',checkout:checkout?checkout+'+07:00':'',returnMode:v.returnMode,recipient:'',note:v.note||'',evidence:{chat:!!v.chat,label:!!v.label,weigh:!!v.weigh,receipt:!!v.receipt,checkoutApproval:!!v.checkoutApproval},history:[]};if(db.orders.some(x=>x.id===o.id))throw Error('Nomor label sudah terpakai. Minta rentang baru kepada Owner.');db.orders.unshift(o);db.settings.labelNext++;history(o,'Order dicatat: '+o.mode+' · '+o.bags+' kantong');if(v.requestId){const r=db.requests.find(r=>r.id===v.requestId);if(!r||r.status!=='Baru')throw Error('Permintaan sudah diproses.');r.status='Diproses · '+o.id;r.orderId=o.id;}return 'Order '+o.id+' tersimpan.';},
evidence(v,f){canEdit();const o=db.orders.find(o=>o.id===f.dataset.id);if(!o||['Selesai','Dibatalkan'].includes(o.stage))throw Error('Order ditutup. Gunakan koreksi Owner.');if(v.weight!==undefined||v.quantity!==undefined){const weight=finite(v.weight||0,'Berat final',0,1000),quantity=finite(v.quantity||0,'Jumlah barang',0,1000),q=THServices.quote(THServices.snapshot(o),weight,quantity);if(!q.minimumMet)throw Error(THServices.rule(THServices.snapshot(o)));if(paid(o)&&(weight!==o.weight||q.total!==o.total))throw Error('Jumlah order lunas perlu koreksi Owner.');if(o.priceAdjustment&&(weight!==o.weight||q.quantity!==o.quantity))throw Error('Jumlah dengan koreksi harga memerlukan koreksi Owner.');o.weight=weight;if(o.serviceSnapshot){o.quantity=q.quantity;o.billedQuantity=q.billedQuantity;}o.total=q.total+(o.priceAdjustment?.amount||0);}const incoming={};for(const k of ['chat','label','pickup','pickupAck','weigh','receipt','qc','packed','readyMessage','handover','customerAck','thirdParty'])incoming[k]=!!v[k];if(stages.indexOf(o.stage)>=3&&['chat','label','weigh','receipt'].some(k=>o.evidence[k]&&!incoming[k]))throw Error('Bukti penerimaan yang sudah dipakai tidak boleh dihapus. Catat koreksi atau tahan order.');if(incoming.customerAck&&!incoming.handover)throw Error('Konfirmasi customer memerlukan bukti penyerahan.');if(incoming.handover&&!['Siap Diserahkan','Dalam Pengantaran'].includes(o.stage))throw Error('Penyerahan dicatat setelah order siap.');if(incoming.handover&&!String(v.recipient||'').trim())throw Error('Nama penerima wajib untuk bukti serah.');if(incoming.handover&&v.recipient.trim().toLowerCase()!==o.customer.toLowerCase()&&!incoming.thirdParty)throw Error('Penerima pihak lain memerlukan izin tertulis customer.');if(!db.employees.some(e=>e.id===v.pic&&e.active))throw Error('Pilih PIC aktif.');o.evidence={...o.evidence,...incoming};o.recipient=v.recipient||'';o.evidenceRef=v.evidenceRef;o.rack=v.rack;o.pic=v.pic;if(incoming.handover&&!o.handoverAt)o.handoverAt=new Date().toISOString();history(o,'Bukti simulasi / PIC diperbarui: '+Object.keys(incoming).filter(k=>incoming[k]).join(', '));return {message:'Bukti dan penugasan disimpan.',reopen:()=>orderDetail(o.id)};},
payment(v,f){canEdit();const o=db.orders.find(o=>o.id===f.dataset.id);if(!o||paid(o)||o.stage==='Dibatalkan')throw Error('Pembayaran order ini sudah tercatat atau order dibatalkan.');const amount=finite(v.amount,'Nominal',0,1e8);if(amount!==o.total||o.total<=0||!o.evidence.weigh)throw Error('Timbang terlebih dahulu dan cocokkan nominal dengan tagihan final.');requireText(v.reference,'Referensi');if(v.method==='Cash'){if(!v.cashReceipt)throw Error('Konfirmasi hitung cash dan kuitansi resmi terlebih dahulu.');if(db.settings.receiptNext>db.settings.receiptEnd)throw Error('Rentang kuitansi habis. Hubungi Owner.');if(v.location==='Kamar saat pengembalian'&&(!['Siap Diserahkan','Dalam Pengantaran','Selesai'].includes(o.stage)||!v.roomCash))throw Error('Cash di kamar hanya saat pengembalian order siap, dengan konfirmasi customer dan pouch segel.');o.receipt='CSH-'+String(db.settings.receiptNext).padStart(4,'0');if(db.orders.some(x=>x.id!==o.id&&x.receipt===o.receipt))throw Error('Nomor kuitansi telah terpakai.');db.settings.receiptNext++;o.payment='Lunas Cash';o.cashLocation=v.location;o.cashCustomerConfirmed=!!v.roomCash;}else{if(v.verified&&ui.role!=='Owner')throw Error('Hanya Owner memverifikasi mutasi. Operator dapat mencatat bukti tanpa mencentang verifikasi.');o.payment=v.verified?'Lunas Terverifikasi':'Menunggu Verifikasi';}o.method=v.method;o.paymentRef=v.reference;o.paidAt=new Date().toISOString();history(o,`${o.payment}: ${money(amount)} · ${v.method} · ${v.reference}${o.receipt?' · '+o.receipt:''}`);return {message:'Pembayaran demo dicatat.',reopen:()=>orderDetail(o.id)};},
tenant(v,f){canEdit();requireText(v.name,'Nama');requireText(v.room,'Kamar');if(v.end<v.start)throw Error('Akhir tinggal harus setelah tanggal mulai.');const duplicate=db.tenants.find(t=>t.id!==f.dataset.id&&t.room.toLowerCase()===v.room.trim().toLowerCase()&&t.status==='Aktif'&&v.status==='Aktif'&&v.start<=t.end&&v.end>=t.start);if(duplicate)throw Error('Kamar sudah dipakai penghuni aktif pada periode yang tumpang tindih.');const t=db.tenants.find(t=>t.id===f.dataset.id);if(t&&v.status!=='Aktif'&&db.orders.some(o=>o.tenantId===t.id&&!['Selesai','Dibatalkan'].includes(o.stage)))throw Error('Selesaikan laundry penghuni sebelum check-out atau arsip.');const data={name:v.name.trim(),contact:v.contact,room:v.room.trim(),building:v.building,type:v.type,start:v.start,end:v.end,rent:finite(v.rent,'Nilai sewa'),note:v.note,status:v.status};if(t){audit('Penghuni '+t.id+' diperbarui: '+JSON.stringify(t)+' → '+JSON.stringify(data));Object.assign(t,data);}else{db.tenants.push({id:uid(),...data});audit('Penghuni demo ditambahkan: '+v.name)}return 'Data penghuni tersimpan.';},
invoice(v){canEdit();if(!getTenant(v.tenantId))throw Error('Penghuni tidak ditemukan.');const i={id:'INV-'+uid().toUpperCase(),tenantId:v.tenantId,title:requireText(v.title,'Periode'),issuedDate:v.issuedDate||ui.date,serviceDate:v.serviceDate||'',recognitionApproved:ui.role==='Owner'&&!!v.recognitionApproved,amount:finite(v.amount,'Nominal',1),paid:0,due:v.due,history:[]};db.invoices.unshift(i);audit(i.id+': tagihan '+money(i.amount)+' dibuat');return 'Tagihan hunian dibuat.';},
'invoice-pay'(v,f){canEdit();const i=db.invoices.find(i=>i.id===f.dataset.id);const amount=finite(v.amount,'Penerimaan',1,i.amount-i.paid);requireText(v.reference,'Referensi');i.paid+=amount;i.history.push({amount,method:v.method,reference:v.reference,actor:actor(),at:new Date().toISOString()});audit(i.id+': penerimaan '+money(amount)+' · '+v.reference);return {message:'Penerimaan dicatat. Sisa tagihan diperbarui.',reopen:()=>invoiceDetail(i.id)};},
report(v,f){canEdit();const e=db.employees.find(e=>e.id===v.employeeId);if(!e||!e.active)throw Error('Pilih karyawan aktif.');if(ui.role==='Operator'&&e.id!==ui.employee)throw Error('Petugas hanya dapat mengirim laporan sendiri.');const old=db.reports.find(r=>r.id===f.dataset.id);if(old&&ui.role==='Operator'&&old.employeeId!==ui.employee)throw Error('Laporan bukan milik petugas ini.');const hours=finite(v.hours,'Durasi',0.1,24),sum=db.reports.filter(r=>r.id!==old?.id&&r.employeeId===e.id&&r.date===v.date).reduce((n,r)=>n+r.hours,0);if(sum+hours>24)throw Error('Total laporan karyawan pada tanggal ini melebihi 24 jam.');const r={employeeId:e.id,date:v.date,division:v.division,activity:requireText(v.activity,'Aktivitas'),output:requireText(v.output,'Hasil'),hours,obstacle:v.obstacle,next:requireText(v.next,'Rencana'),orderId:v.division==='Laundry'?v.orderId:'',evidence:v.evidence,status:'Dikirim',submittedAt:new Date().toISOString()};if(old){audit('Laporan '+old.id+' diperbarui. Sebelumnya: '+JSON.stringify(old));Object.assign(old,r)}else{db.reports.unshift({id:uid(),feedback:'',...r});audit('Laporan '+v.division+' '+e.name+' untuk '+v.date+' dikirim')}return 'Laporan tersimpan dan dapat ditinjau Owner.';},
'review-report'(v,f){ownerOnly();const r=db.reports.find(r=>r.id===f.dataset.id);r.feedback=requireText(v.feedback,'Feedback');r.status=v.status;r.reviewedAt=new Date().toISOString();audit('Owner meninjau laporan '+r.id+': '+v.status+' · '+v.feedback);return 'Tinjauan laporan disimpan.';},
employee(v,f){ownerOnly();const e=db.employees.find(e=>e.id===f.dataset.id),data={name:requireText(v.name,'Nama'),position:requireText(v.position,'Jabatan'),division:v.division,color:v.color};if(e){audit('Profil '+e.id+' diperbarui: '+JSON.stringify(e)+' → '+JSON.stringify(data));Object.assign(e,data)}else{db.employees.push({id:uid(),active:true,...data});audit('Karyawan demo ditambahkan: '+data.name)}return 'Profil karyawan tersimpan.';},
'employee-toggle'(v,f){ownerOnly();const e=db.employees.find(e=>e.id===f.dataset.id);if(e.active){const os=db.orders.filter(o=>o.pic===e.id&&!['Selesai','Dibatalkan'].includes(o.stage));if(os.length)throw Error('Alihkan PIC order '+os.map(o=>o.id).join(', ')+' dahulu melalui Detail Order.');if(db.employees.filter(e=>e.active).length<=1)throw Error('Sisakan minimal satu karyawan aktif.');}e.active=!e.active;if(!e.active&&ui.employee===e.id)ui.employee=db.employees.find(e=>e.active).id;audit(e.name+' '+(e.active?'diaktifkan':'dinonaktifkan')+'; riwayat dipertahankan');return 'Status karyawan diperbarui.';},
evaluation(v,f){ownerOnly();if(!db.employees.some(e=>e.id===v.employeeId))throw Error('Karyawan tidak ditemukan.');const scores=scoreKeys.map((k,i)=>finite(v['score'+i],k,1,5));if(scores.some(x=>!Number.isInteger(x)))throw Error('Skor harus bilangan bulat.');if(f.dataset.id&&db.evaluations.some(x=>x.id!==f.dataset.id&&x.employeeId===v.employeeId&&x.date===v.date))throw Error('Karyawan sudah memiliki penilaian pada tanggal ini. Buka penilaian yang sudah ada.');const existing=db.evaluations.find(x=>x.id===f.dataset.id)||db.evaluations.find(x=>x.employeeId===v.employeeId&&x.date===v.date);const data={employeeId:v.employeeId,date:v.date,scores,evidence:requireText(v.evidence,'Bukti'),feedback:requireText(v.feedback,'Feedback'),next:requireText(v.next,'Rencana perbaikan'),at:new Date().toISOString()};if(existing){audit('Penilaian '+existing.id+' diperbarui. Sebelumnya: '+JSON.stringify(existing));Object.assign(existing,data)}else{db.evaluations.unshift({id:uid(),...data});audit('Penilaian '+getEmp(v.employeeId)+' tanggal '+v.date+' disimpan')}return 'Penilaian enam aspek tersimpan.';},
settlement(v){canEdit();const os=db.orders.filter(o=>o.payment==='Lunas Cash'&&!o.settlementId),expectedDeposit=os.reduce((n,o)=>n+o.total,0);if(!os.length)throw Error('Tidak ada cash yang belum closing.');const float=finite(v.float,'Float',0,1e8),physical=finite(v.physical,'Uang fisik',0,1e8),recount=finite(v.recount,'Hitung ulang',0,1e8);if(physical!==recount)throw Error('Hitung pertama dan hitung ulang berbeda. Hitung kembali dengan saksi.');if(physical<float)throw Error('Cash fisik kurang dari float. Catat insiden dan telusuri float sebelum closing.');if(!v.confirmed)throw Error('Selesaikan pencocokan kuitansi, hitung bersama, segel, dan penyimpanan.');if(ui.role==='Operator'&&v.witness===ui.employee)throw Error('Saksi harus berbeda dari petugas closing.');if(!db.employees.some(e=>e.id===v.witness&&e.active))throw Error('Saksi aktif wajib dipilih.');const difference=physical-float-expectedDeposit;if(difference&&!v.note.trim())throw Error('Selisih harus disertai penyebab dan tindak lanjut.');let id='CASH-'+v.date.replaceAll('-','')+'-'+v.shift;if(db.settlements.some(s=>s.id===id))throw Error('Shift ini sudah closing. Pilih shift berikutnya.');const s={id,date:v.date,shift:v.shift,float,physical,recount,expectedDeposit,deposit:physical-float,difference,witness:getEmp(v.witness),depositor:getEmp(v.depositor),envelope:requireText(v.envelope,'Amplop'),seal:requireText(v.seal,'Segel'),keyHolder:requireText(v.keyHolder,'Pemegang kunci'),note:v.note,orderIds:os.map(o=>o.id),receiptIds:os.map(o=>o.receipt),status:'Belum Disetor',createdAt:new Date().toISOString(),createdBy:actor()};os.forEach(o=>o.settlementId=id);db.settlements.unshift(s);audit(id+': closing '+money(expectedDeposit)+', selisih '+money(difference));return 'Closing cash disimpan. Pembayaran customer tetap Lunas Cash.';},
deposit(v,f){canEdit();const s=db.settlements.find(s=>s.id===f.dataset.id);if(s.status!=='Belum Disetor')throw Error('Setoran sudah dicatat.');if(finite(v.amount,'Nominal',0,1e8)!==s.deposit)throw Error('Setor utuh sesuai cash setelah float. Nominal tidak cocok.');s.depositRef=requireText(v.reference,'Bukti setor');s.depositAt=v.at;s.status='Sudah Disetor';audit(s.id+': setoran '+money(s.deposit)+' dicatat, menunggu Owner');return {message:'Bukti setoran tersimpan.',reopen:()=>settlementDetail(s.id)};},
'verify-settlement'(v,f){ownerOnly();const s=db.settlements.find(s=>s.id===f.dataset.id);TH.settleVerify(s,ui.role,Number(v.amount),v.reference);audit(s.id+': mutasi cocok '+money(s.deposit)+' · '+v.reference);return {message:'Setoran terverifikasi oleh Owner.',reopen:()=>settlementDetail(s.id)};},
'resolve-difference'(v,f){ownerOnly();const s=db.settlements.find(s=>s.id===f.dataset.id);s.resolution=requireText(v.resolution,'Tindak lanjut');s.resolved=true;if(s.status.startsWith('Terverifikasi'))s.status='Terverifikasi Owner';s.resolvedAt=new Date().toISOString();audit(s.id+': tindak lanjut selisih '+money(s.difference)+' · '+v.resolution);return 'Tindak lanjut disimpan. Nilai selisih historis tetap tersedia.';},
hold(v,f){canEdit();const o=db.orders.find(o=>o.id===f.dataset.id);if(['Selesai','Dibatalkan'].includes(o.stage))throw Error('Order sudah ditutup.');if(v.action==='Dibatalkan'){ownerOnly();if(paid(o))throw Error('Order sudah dibayar. Tahan order dan selesaikan proses refund terpisah sebelum pembatalan.');o.voidLabel=true;}else if(o.stage!=='Tertahan')o.resumeStage=o.stage;o.stage=v.action;o.note=requireText(v.reason,'Alasan');history(o,v.action+': '+v.reason);return 'Status dan alasan dicatat tanpa menghapus order.';},
resume(v,f){canEdit();const o=db.orders.find(o=>o.id===f.dataset.id);if(o.stage!=='Tertahan')throw Error('Order tidak tertahan.');requireText(v.reason,'Penyelesaian');o.stage=o.resumeStage||'Pesanan Masuk';history(o,'Masalah diselesaikan, kembali ke '+o.stage+': '+v.reason);return 'Order dilanjutkan dari tahap sebelumnya.';},
correction(v,f){ownerOnly();const o=db.orders.find(o=>o.id===f.dataset.id),weight=finite(v.weight||0,'Berat',0,1000),q=THServices.quote(THServices.snapshot(o),weight,Number(v.quantity||0)),total=finite(v.total,'Tagihan',0,1e8),reason=requireText(v.reason,'Alasan/bukti');if(window.THCloud?.state?.finance?.transactions.some(t=>t.sourceType==='laundry'&&t.orderId===o.id&&t.kind==='service'))throw Error('Order sudah terhubung ke Laporan. Nilai layanan dikunci agar order dan laporan tetap cocok.');if(reason.length<5)throw Error('Alasan koreksi minimal 5 karakter.');if(!q.minimumMet)throw Error(THServices.rule(THServices.snapshot(o)));if(paid(o)&&(total!==o.total||q.quantity!==(o.quantity??o.weight)))throw Error('Order yang sudah dibayar perlu penyesuaian terpisah.');const old={weight:o.weight,quantity:o.quantity,total:o.total};o.weight=weight;o.total=total;if(o.serviceSnapshot){o.quantity=q.quantity;o.billedQuantity=q.billedQuantity;o.priceAdjustment={amount:total-q.total,reason};}history(o,'Koreksi Owner: '+JSON.stringify(old)+' → '+JSON.stringify({weight,quantity:q.quantity,total})+' · '+reason);return 'Koreksi tercatat beserta nilai lama dan baru.';},
settings(v){ownerOnly();const old=JSON.stringify(db.settings),s=db.settings;const nextLabel=finite(v.labelNext,'Nomor label',s.labelNext),labelEnd=finite(v.labelEnd,'Batas label',nextLabel),nextReceipt=finite(v.receiptNext,'Nomor kuitansi',s.receiptNext),receiptEnd=finite(v.receiptEnd,'Batas kuitansi',nextReceipt);if([nextLabel,labelEnd,nextReceipt,receiptEnd].some(x=>!Number.isInteger(x)))throw Error('Nomor seri harus bilangan bulat.');if(v.hoursClose<=v.hoursOpen)throw Error('Jam tutup harus setelah jam buka.');const packages=Object.keys(v).filter(k=>/^packageName[0-9]+$/.test(k)).map(k=>Number(k.slice(11))).map(i=>serviceFromFields(v,i));if(!packages.length)throw Error('Minimal satu paket layanan harus diisi.');if(new Set(packages.map(p=>p.name.toLowerCase())).size!==packages.length)throw Error('Nama layanan tidak boleh berulang.');Object.assign(s,{date:v.date,hoursOpen:v.hoursOpen,hoursClose:v.hoursClose,responseMinutes:finite(v.responseMinutes,'Respons',1,120),closingMinutes:finite(v.closingMinutes,'Closing',1,180),float:finite(v.float,'Float',0,1e8),maxCash:finite(v.maxCash,'Batas cash',1,1e8),depositTime:v.depositTime,labelNext:nextLabel,labelEnd,receiptNext:nextReceipt,receiptEnd,packages,configured:true});ui.date=s.date;audit('Parameter diperbarui: '+old+' → '+JSON.stringify(s));return 'Pengaturan demo disimpan.';},
'consumer-request'(v){if(ui.role!=='Konsumen')throw Error('Gunakan portal konsumen.');if(getTenant(ui.consumer)?.status!=='Aktif')throw Error('Masa tinggal tidak aktif. Permintaan baru perlu dicatat petugas.');const bags=finite(v.bags,'Jumlah kantong',1,26);if(!Number.isInteger(bags))throw Error('Jumlah kantong harus bulat.');db.requests.unshift({id:uid(),tenantId:ui.consumer,bags,time:v.time,returnMode:v.returnMode,note:v.note,status:'Baru',createdAt:new Date().toISOString()});audit('Customer demo '+getTenant(ui.consumer).name+' meminta jemput '+bags+' kantong');return 'Permintaan tercatat. Operator dapat memprosesnya di perangkat ini.';},
'request-reject'(v,f){canEdit();const r=db.requests.find(r=>r.id===f.dataset.id);if(!r||r.status!=='Baru')throw Error('Permintaan sudah ditangani.');r.reason=requireText(v.reason,'Alasan');r.status='Ditolak · '+r.reason;audit('Permintaan '+r.id+' ditolak: '+r.reason);return 'Penolakan dicatat dengan alasan.';},
reset(){ownerOnly();db=TH.seed();ui.date=db.settings.date;ui.employee='e1';audit('Data direset ke skenario awal demo.');return 'Data demo dikembalikan ke awal.';},
restore(){ownerOnly();if(!TH.validateBackup(window.pendingRestore))throw Error('Cadangan tidak valid.');db=window.pendingRestore;delete window.pendingRestore;ui.date=db.settings.date;ui.employee=db.employees.find(e=>e.active)?.id||'';audit('Data dipulihkan dari cadangan lokal.');return 'Cadangan dipulihkan.';}
};
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const snapshot=JSON.stringify(db);try{if(window.THCloud?.busy)throw Error('Masih menyimpan. Tunggu sampai selesai.');if(f.dataset.conflicted)throw Error('Salin input bila perlu, lalu tutup dan buka formulir kembali untuk meninjau versi terbaru.');const v=Object.fromEntries(new FormData(f));const result=await submissions[f.dataset.form](v,f);if(result===false)return;await persist(typeof result==='string'?result:result?.message||'Tersimpan.');closeModal();result?.reopen?.();}catch(err){db=JSON.parse(window.THCloud?.state?JSON.stringify(THCloud.state.operations):snapshot);if(err.httpStatus===409)f.dataset.conflicted='true';const target=f.querySelector('.form-error');if(target){target.textContent=err.message||'Periksa kembali data yang diisi.';target.scrollIntoView({block:'nearest'});}else toast(err.message);}});
