if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_laundry_summary',title:'Baca ringkasan laundry lokal',description:'Read the same fictional laundry summary visible to the current demo role.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){if(!window.THAccess?.bind())throw Error('Masuk ke akun demo terlebih dahulu.');const rows=ui.role==='Konsumen'?db.orders.filter(o=>o.tenantId===ui.consumer):db.orders;return {role:ui.role,date:ui.date,orders:rows.map(o=>({id:o.id,stage:o.stage,payment:o.payment,total:o.total}))}}},{signal:life.signal})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'open_daily_activity_form',title:'Buka form laporan harian',description:'Open the visible daily activity form. Does not create or submit a report.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){canEdit();reportForm();return {opened:true,submitted:false}}},{signal:life.signal})).catch(()=>{});window.addEventListener('pagehide',()=>life.abort(),{once:true});}catch{}}
